def dehydrate_timedelta(value):
    """ Dehydrator for `timedelta` values.

    :param value:
    :type value: timedelta
    :return: a string representation of the total seconds or None if value is not a timedelta.
    """
    if value is None:
        return None
    try:
        total_seconds = value.total_seconds()
    except AttributeError:
        return None

    # Ensure the result is an integer number of seconds.
    try:
        seconds = int(round(total_seconds))
    except (OverflowError, ValueError):
        return None

    return str(seconds)

def keys(self):
    """ Return the keys of the record.

    :return: list of key names
    """
    try:
        # Prefer self._keys if it exists and is a dict-like structure
        if hasattr(self, "_keys") and isinstance(self._keys, dict):
            return list(self._keys.keys())
        # Fallback to a record attribute that might hold the data
        if hasattr(self, "_record") and isinstance(self._record, dict):
            return list(self._record.keys())
        # If neither attribute exists, return an empty list
        return []
    except Exception:
        # In case of any unexpected error, safely return an empty list
        return []

def protocol_handlers(cls, protocol_version=None):
    """Return a dictionary of available Bolt protocol handlers,
    keyed by version tuple. If an explicit protocol version is
    provided, the dictionary will contain either zero or one items,
    depending on whether that version is supported. If no protocol
    version is provided, all available versions will be returned.

    :param protocol_version: tuple identifying a specific protocol
        version (e.g. (3, 5)) or None
    :return: dictionary of version tuple to handler class for all
        relevant and supported protocol versions
    :raise TypeError: if protocol version is not passed in a tuple
    """
    if protocol_version is not None and not isinstance(protocol_version, tuple):
        raise TypeError("protocol_version must be a tuple or None")

    handlers = {}

    # First, look for explicit mappings defined on the class.
    mapping_names = ("handlers", "HANDLERS", "_handlers")
    for name in mapping_names:
        mapping = getattr(cls, name, None)
        if isinstance(mapping, dict):
            for version, handler_cls in mapping.items():
                if isinstance(version, tuple) and handler_cls is not None:
                    handlers[version] = handler_cls

    # Second, inspect nested types that may represent handlers.
    for obj in cls.__dict__.values():
        if isinstance(obj, type) and hasattr(obj, "_protocol_version"):
            version = getattr(obj, "_protocol_version")
            if isinstance(version, tuple) and obj is not None:
                handlers[version] = obj

    if protocol_version is not None:
        return {protocol_version: handlers[protocol_version]} if protocol_version in handlers else {}

    return dict(handlers)

def index(self, key):
    """ Return the index of the given item.

    :param key: a key
    :return: index
    :rtype: int
    """
    try:
        # Prefer a dedicated index list if present
        if hasattr(self, "_index"):
            return self._index.index(key)
        # Fallback to the data container
        return self._data.index(key)
    except (AttributeError, ValueError):
        raise KeyError(f"Key not found: {key}")

def values(self, *keys):
    """
    Return the values of the record, optionally filtering to
    include only certain values by index or key.

    :param keys: indexes or keys of the items to include; if none
                 are provided, all values will be included
    :return: list of values
    :rtype: list
    """
    if not hasattr(self, "_items"):
        raise AttributeError("Object does not have _items attribute required for values()")

    # If no keys specified, return all values
    if not keys:
        try:
            # _items is expected to be a dict-like object
            return list(self._items.values())
        except AttributeError:
            # Fall back for iterable containers that support direct indexing
            return list(self._items)

    # When specific keys or indices are requested
    results = []
    for key in keys:
        try:
            results.append(self._items[key])
        except (KeyError, IndexError, TypeError) as err:
            raise KeyError(f"Key or index {key!r} not found in record.") from err
    return results

def data(self, *keys):
    """
    Return the keys and values of this record as a dictionary,
    optionally including only certain values by index or key. Keys
    provided in the items that are not in the record will be
    inserted with a value of :const:`None`; indexes provided
    that are out of bounds will trigger an :exc:`IndexError`.

    :param keys: indexes or keys of the items to include; if none
                  are provided, all values will be included
    :return: dictionary of values, keyed by field name
    :raises: :exc:`IndexError` if an out-of-bounds index is specified
    """
    # Determine the underlying data structure that holds the record values
    _data = None
    if isinstance(self, dict):
        _data = self
    elif hasattr(self, "_data") and isinstance(getattr(self, "_data"), dict):
        _data = getattr(self, "_data")
    elif hasattr(self, "_attrs") and isinstance(getattr(self, "_attrs"), dict):
        _data = getattr(self, "_attrs")
    elif hasattr(self, "__dict__"):
        # Exclude private/internal attributes that are likely not fields
        _data = {k: v for k, v in self.__dict__.items()
                 if not k.startswith("_")}
    else:
        raise TypeError("Object does not provide a dictionary of fields")

    # If no keys provided, return a shallow copy of all key/value pairs
    if not keys:
        return dict(_data)

    # Prepare the list of field names to support index access
    _field_names = list(_data.keys())
    result = {}

    for key in keys:
        if isinstance(key, int) and not isinstance(key, bool):
            # Index-based access
            idx = key
            if idx < 0 or idx >= len(_field_names):
                raise IndexError(
                    f"index {idx} out of bounds for record with {len(_field_names)} fields"
                )
            field_name = _field_names[idx]
            result[field_name] = _data.get(field_name)
        else:
            # Name-based access
            field_name = str(key)
            if field_name in _data:
                result[field_name] = _data[field_name]
            else:
                result[field_name] = None

    return result

def pop_u16(self):
        """ Remove the last two bytes of data, returning them as a big-endian
        16-bit unsigned integer.
        """
        if len(self.data) < 2:
            raise ValueError("Not enough data to pop 2 bytes")
        value_bytes = self.data[-2:]
        del self.data[-2:]
        return self.unpack('>H', 2)

def begin(self, mode=None, bookmarks=None, metadata=None, timeout=None,
          db=None, imp_user=None, dehydration_hooks=None,
          hydration_hooks=None, **handlers):
    """
    Appends a BEGIN message to the output queue.

    :param mode: access mode for routing - "READ" or "WRITE" (default)
    :param bookmarks: iterable of bookmark values after which this transaction should begin
    :param metadata: custom metadata dictionary to attach to the transaction
    :param timeout: timeout for transaction execution (seconds)
    :param db: name of the database against which to begin the transaction
        Requires Bolt 4.0+.
    :param imp_user: the user to impersonate
        Requires Bolt 4.4+
    :param dehydration_hooks:
        Hooks to dehydrate types (dict from type (class) to dehydration
        function). Dehydration functions receive the value and returns an
        object of type understood by packstream.
    :param hydration_hooks:
        Hooks to hydrate types (mapping from type (class) to dehydration function). Dehydration functions receive the value of
        type understood by packstream and are free to return anything.
    :param handlers: handler functions passed into the returned Response object
    :return: Response object
    """
    # Validate mode
    if mode is not None and mode not in ("READ", "WRITE"):
        raise ValueError(f"Invalid mode {mode!r}. Must be 'READ' or 'WRITE'.")
    resolved_mode = mode or "WRITE"

    # Normalise bookmarks
    if bookmarks is None:
        resolved_bookmarks = ()
    else:
        # Ensure bookmarks is an iterable of strings, not a single string
        if isinstance(bookmarks, (str, bytes)):
            resolved_bookmarks = (bookmarks,)
        else:
            resolved_bookmarks = tuple(bookmarks)

    # Validate metadata
    resolved_metadata = {} if metadata is None else dict(metadata)

    # Apply dehydration hooks to the metadata values
    if dehydration_hooks:
        for key, val in list(resolved_metadata.items()):
            hook = dehydration_hooks.get(type(val))
            if hook:
                try:
                    resolved_metadata[key] = hook(val)
                except Exception as exc:
                    raise ValueError(
                        f"Error in dehydration hook for type {type(val).__name__}"
                    ) from exc

    # Construct the BEGIN message payload
    begin_msg = {
        "message_type": "BEGIN",
        "mode": resolved_mode,
        "bookmarks": list(resolved_bookmarks),
        "metadata": resolved_metadata,
    }
    if timeout is not None:
        begin_msg["timeout"] = timeout
    if db is not None:
        begin_msg["database"] = db
    if imp_user is not None:
        begin_msg["impersonated_user"] = imp_user

    # Append to output queue.  The queue attribute name may differ in the
    # actual implementation – we use a common placeholder here.
    if hasattr(self, "_output_queue"):
        self._output_queue.append(begin_msg)
    elif hasattr(self, "_queue"):
        self._queue.append(begin_msg)
    else:
        # Fallback: try to use a generic send method if available
        send_method = getattr(self, "send_message", None)
        if callable(send_method):
            send_method(begin_msg)
        else:
            raise AttributeError(
                "Cannot find an output queue or message sender on this session."
            )

    # Create and return a Response object, passing along any handler
    # callbacks supplied by the caller.
    if handlers:
        return Response(**handlers)
    return Response()

def deprecated(message):
    """Decorator for deprecating functions and methods.

    ::

        @deprecated("'foo' has been deprecated in favour of 'bar'")
        def foo(x):
            pass

    """

    import warnings
    import functools

    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            warnings.warn(message, category=DeprecationWarning, stacklevel=2)
            return func(*args, **kwargs)
        return wrapper

    return decorator

def parse_version(s: str) -> tuple[int, ...]:
    """poor man's version comparison"""

    if not isinstance(s, str):
        raise TypeError(f"Expected a string, got {type(s).__name__}")

    # Trim whitespace and split on periods
    parts = s.strip().split('.')
    nums = []

    # Use regex to extract leading digits from each part
    import re
    for part in parts:
        if part == '':
            # Represent an empty segment as zero
            nums.append(0)
            continue

        m = re.match(r'(\d+)', part)
        if m:
            nums.append(int(m.group(1)))
        else:
            # If no initial digits, treat as zero
            nums.append(0)

    return tuple(nums)

def cached(cache, key=hashkey, lock=None):
    """Decorator to wrap a function with a memoizing callable that saves
    results in a cache.
    """
    def decorator(func):
        if cache is None:
            def wrapper(*args, **kwargs):
                return func(*args, **kwargs)
        elif lock is None:
            def wrapper(*args, **kwargs):
                k = key(*args, **kwargs)
                try:
                    return cache[k]
                except KeyError:
                    pass  # key not found
                v = func(*args, **kwargs)
                try:
                    cache[k] = v
                except ValueError:
                    pass  # value too large
                return v
        else:
            def wrapper(*args, **kwargs):
                k = key(*args, **kwargs)
                try:
                    with lock:
                        return cache[k]
                except KeyError:
                    pass  # key not found
                v = func(*args, **kwargs)
                try:
                    with lock:
                        cache[k] = v
                except ValueError:
                    pass  # value too large
                return v
        return _update_wrapper(wrapper, func)
    return decorator

def mru_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Most Recently Used (MRU) algorithm.
    """
    def decorator(func):
        cache = {}
        order = []

        def make_key(*args, **kwargs):
            if typed:
                args_key = tuple((arg, type(arg)) for arg in args)
                kwargs_key = tuple((k, v, type(v)) for k, v in sorted(kwargs.items()))
            else:
                args_key = tuple(args)
                kwargs_key = tuple(sorted(kwargs.items()))
            return (args_key, kwargs_key)

        def wrapper(*args, **kwargs):
            key = make_key(*args, **kwargs)
            if key in cache:
                # Update recency: move key to the end
                order.remove(key)
                order.append(key)
                return cache[key]
            result = func(*args, **kwargs)
            cache[key] = result
            order.append(key)
            if len(cache) > maxsize:
                # Evict the oldest entry to maintain size
                old_key = order.pop(0)
                del cache[old_key]
            return result

        return wrapper
    return decorator

def popitem(self):
        """Remove and return the `(key, value)` pair first inserted."""
        try:
            key = next(iter(self))
        except StopIteration:
            raise KeyError('popitem() called on an empty container')
        value = self.pop(key)
        return key, value

def setdefault(self, key, default=None):
        """ D.setdefault(k[,d]) -> D.get(k,d), also set D[k]=d if k not in D """
        storage = getattr(self, "storage", None)
        if storage is None:
            raise AttributeError("The object does not have a 'storage' attribute to use.")
        try:
            if key in storage:
                return storage[key]
        except Exception as exc:
            raise KeyError(f"Invalid key {key}") from exc
        storage[key] = default
        return default

def get(self, key, default=None):
        """
        D.get(k[,d]) -> D[k] if k in D, else d.  d defaults to None.
        """
        try:
            return self[key]
        except KeyError:
            return default

def cachedmethod(cache, key=hashkey, lock=None):
    """Decorator to wrap a class or instance method with a memoizing
    callable that saves results in a cache.

    """

    def decorator(method):
        if lock is None:
            def wrapper(self, *args, **kwargs):
                c = cache(self)
                if c is None:
                    return method(self, *args, **kwargs)
                k = key(*args, **kwargs)
                try:
                    return c[k]
                except KeyError:
                    pass  # key not found
                v = method(self, *args, **kwargs)
                try:
                    c[k] = v
                except ValueError:
                    pass  # value too large
                return v
        else:
            def wrapper(self, *args, **kwargs):
                c = cache(self)
                if c is None:
                    return method(self, *args, **kwargs)
                k = key(*args, **kwargs)
                try:
                    with lock(self):
                        return c[k]
                except KeyError:
                    pass  # key not found
                v = method(self, *args, **kwargs)
                try:
                    with lock(self):
                        c[k] = v
                except ValueError:
                    pass  # value too large
                return v
        return _update_wrapper(wrapper, method)
    return decorator

@staticmethod
def is_file_exist(file_name):
    """
    Check if file name exist.
    :param file_name: File name.
    :type file_name: str
    :return: Return true (exist), false (do not exist, or invalid file name)
    :rtype bool
    """
    if not isinstance(file_name, str) or not file_name.strip():
        return False
