def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    if classes is None:
        return []
    try:
        classes = list(classes)
    except TypeError:
        raise TypeError("classes must be an iterable of classes")
    result = []
    for cls in classes:
        if not isinstance(cls, type):
            raise TypeError(f"{cls!r} is not a class")
        # Skip duplicate classes
        if cls in result:
            continue
        # Remove any existing superclasses of cls
        result = [c for c in result if not issubclass(cls, c)]  # cls is subclass of c -> c is super, remove
        # If any existing subclass of cls, then cls is a super class; skip adding
        if any(issubclass(c, cls) and c is not cls for c in result):
            continue
        result.append(cls)
    return result

def namesAndDescriptions(self, all=False):  # pylint:disable=redefined-builtin
    """Return attribute names and descriptions defined by interface."""
    # Validate the optional flag parameter
    if not isinstance(all, bool):
        raise TypeError("'all' must be a bool, not {!r}".format(type(all).__name__))

    # Start with any explicitly defined interface dictionary.
    # It may be present as a class or instance attribute named '_INTERFACE'.
    interface = getattr(self, "_INTERFACE", None)
    if isinstance(interface, dict):
        descriptions = dict(interface)  # copy to avoid mutation
    else:
        descriptions = {}

    if all:
        # Include additional attributes on the instance that are not private.
        # For each attribute, try to obtain a string description from its
        # __doc__ property (or default to an empty string).  Respect any
        # existing entry from the explicit interface.
        for name, value in vars(self).items():
            if name.startswith("_"):
                continue
            if name in descriptions:
                continue
            desc = getattr(value, "__doc__", "")
            if not isinstance(desc, str):
                desc = ""
            descriptions[name] = desc

    return descriptions

def names(self, all=False): # pylint:disable=redefined-builtin
    """Return the attribute names defined by the interface."""
    import inspect
    # Collect names from instance dict
    names = set(self.__dict__.keys())
    # Add class-level attributes
    cls = type(self)
    for name, val in cls.__dict__.items():
        if name.startswith('_'):
            continue
        if isinstance(val, property):
            names.add(name)
            continue
        if inspect.isroutine(val):
            if all:
                names.add(name)
            continue
        names.add(name)
    # Include slots if defined
    slots = getattr(cls, "__slots__", [])
    if isinstance(slots, str):
        slots = [slots]
    for s in slots:
        if not s.startswith('_'):
            names.add(s)
    # Return sorted list for consistency
    return sorted(names)

def _normalizeargs(sequence, output=None):
    """Normalize declaration arguments

    Normalization arguments might contain Declarions, tuples, or single
    interfaces.

    Anything but individial interfaces or implements specs will be expanded.
    """
    if output is None:
        output = []

    if sequence is None:
        return output

    # Do not treat strings or bytes as iterables to be expanded
    if isinstance(sequence, (str, bytes)):
        output.append(sequence)
        return output

    # Prepare names that may be defined in the caller's namespace
    InterfaceClass = None
    Implements = None
    try:
        InterfaceClass = zope.interface.interface.InterfaceClass
    except Exception:
        pass
    try:
        Implements = zope.interface.declarations.Implements
    except Exception:
        pass

    # If the sequence is a class that is an interface or Implements spec, append it
    if isinstance(sequence, type):
        if InterfaceClass is not None and isinstance(sequence, InterfaceClass):
            output.append(sequence)
            return output

    if Implements is not None and isinstance(sequence, Implements):
        output.append(sequence)
        return output

    # If the sequence is an iterable (but not a string/bytes), recurse into its items
    if hasattr(sequence, "__iter__"):
        for item in sequence:
            _normalizeargs(item, output)
        return output

    # Fallback: append the sequence as an individual element
    output.append(sequence)
    return output

def reset(self):
    """Reset the histogram.

    Current context is reset to an empty dict.
    Bins are reinitialized with the *initial_value*
    or with *make_bins()* (depending on the initialization).
    """
    # Reset current context
    if hasattr(self, "current_context"):
        self.current_context = {}
    elif hasattr(self, "context"):
        self.context = {}

    # Reinitialize bins
    if hasattr(self, "initial_value") and self.initial_value is not None:
        # If bins already exist, preserve size
        if hasattr(self, "bins") and isinstance(self.bins, (list, tuple)):
            try:
                size = len(self.bins)
            except Exception:
                size = 1
            # If initial_value is iterable, attempt to match size
            if isinstance(self.initial_value, (list, tuple)) and len(self.initial_value) == size:
                self.bins = list(self.initial_value)
            else:
                self.bins = [self.initial_value] * size
        else:
            # No bins yet – create a single bin
            self.bins = [self.initial_value]
    elif hasattr(self, "make_bins") and callable(self.make_bins):
        try:
            self.bins = self.make_bins()
        except Exception:
            # Fallback if make_bins fails
            self.bins = []
    else:
        # No strategy available – set to empty list
        self.bins = []

def _get_err_indices(self, coord_name):
    """Get error indices corresponding to a coordinate."""
    # Attempt to locate a dedicated error attribute following common naming patterns
    potential_keys = [f"{coord_name}_err", f"{coord_name}_errors", f"errors_{coord_name}"]
    for key in potential_keys:
        # Check if the attribute exists directly on the instance
        if hasattr(self, key):
            val = getattr(self, key)
            # Return directly if the value appears to be an index sequence
            if isinstance(val, (list, tuple)):
                return val
        # Check if the attribute is stored in the Data dictionary
        data_dict = getattr(self, "Data", None)
        if isinstance(data_dict, dict) and key in data_dict:
            val = data_dict[key]
            if isinstance(val, (list, tuple)):
                return val
    # If the instance maintains a map of variables (e.g., self._variables),
    # attempt to pull the error indices from there
    if hasattr(self, "_variables") and isinstance(self._variables, dict):
        for key in potential_keys:
            if key in self._variables:
                var = self._variables[key]
                if hasattr(var, "indexes"):
                    return var.indexes
                if hasattr(var, "index"):
                    return var.index
    # If none of the above paths yielded an index sequence, raise an informative error
    raise KeyError(f"Could not find error indices for coordinate '{coord_name}'.")

def _update_context(self, context):
    """Update *context* with the properties of this graph.

    *context.error* is appended with indices of errors.
    Example subcontext for a graph with fields "E,t,error_E_low":
    {"error": {"x_low": {"index": 2}}}.
    Note that error names are called "x", "y" and "z"
    (this corresponds to first three coordinates,
    if they are present), which allows to simplify plotting.
    Existing values are not removed
    from *context.value* and its subcontexts.

    Called on "destruction" of the graph (for example,
    in :class:`.ToCSV`). By destruction we mean conversion
    to another structure (like text) in the flow.
    The graph object is not really destroyed in this process.
    """
    # Ensure error and value dictionaries exist
    error_ctx = context.setdefault('error', {})
    value_ctx = context.setdefault('value', {})

    # Build a mapping from coordinate field names to short names 'x','y','z'
    coord_names = []
    for attr in vars(self):
        if attr.startswith('_') or attr.startswith('error_'):
            continue
        coord_names.append(attr)
        if len(coord_names) == 3:
            break
    coord_map = {}
    for idx, name in enumerate(coord_names):
        if idx == 0:
            coord_map[name] = 'x'
        elif idx == 1:
            coord_map[name] = 'y'
        elif idx == 2:
            coord_map[name] = 'z'

    # Iterate over instance attributes
    for attr_name, attr_value in vars(self).items():
        if attr_name.startswith('_'):
            continue
        if attr_name.startswith('error_'):
            # Field format: error_{coord}{_suffix}
            rest = attr_name[len('error_'):]
            if '_' in rest:
                coord_part, suffix = rest.rsplit('_', 1)
                coord_short = coord_map.get(coord_part)
                if not coord_short:
                    # If coord_part not found in mapping, skip
                    continue
                key = f'{coord_short}_{suffix}'
            else:
                # No suffix present
                coord_part = rest
                coord_short = coord_map.get(coord_part)
                if not coord_short:
                    continue
                key = coord_short

            # Prepare indices list
            indices = attr_value
            if hasattr(indices, '__iter__') and not isinstance(indices, (str, bytes)):
                indices_list = list(indices)
            else:
                indices_list = [indices]

            # Append to existing error context
            if key not in error_ctx:
                error_ctx[key] = {'index': indices_list}
            else:
                existing = error_ctx[key].get('index', [])
                if isinstance(existing, list):
                    combined = existing + indices_list
                else:
                    combined = [existing] + indices_list
                error_ctx[key]['index'] = combined
        else:
            # Non-error field, store in value context
            value_ctx[attr_name] = attr_value

    # Ensure the updated dictionaries are put back into context
    context['error'] = error_ctx
    context['value'] = value_ctx
    return context

def is_fill_request_seq(seq):
    """Test whether *seq* can be converted to a FillRequestSeq.

    True only if it is a FillRequest element
    or contains at least one such,
    and it is not a Source sequence.
    """
    try:
        # If seq itself is a FillRequest, always true
        if isinstance(seq, FillRequest):
            return True
        # Exclude Source sequences outright
        if isinstance(seq, Source):
            return False
        # Don't treat string/bytes as iterable sequences of interest
        if isinstance(seq, (str, bytes)):
            return False
        # Ensure seq is iterable
        iterator = iter(seq)
    except Exception:
        # Not iterable or other type errors
        return False
    else:
        for item in iterator:
            if isinstance(item, FillRequest):
                return True
        return False

def is_fill_request_el(obj):
    """Object contains executable methods 'fill' and 'request'."""
    try:
        has_fill = hasattr(obj, 'fill') and callable(getattr(obj, 'fill', None))
        has_request = hasattr(obj, 'request') and callable(getattr(obj, 'request', None))
        return has_fill and has_request
    except Exception:
        return False

def is_run_el(obj):
    """Object contains executable method 'run'."""
    try:
        attr = getattr(obj, 'run')
    except Exception:
        return False
    return callable(attr)

def is_fill_compute_el(obj):
    """Object contains executable methods 'fill' and 'compute'."""
    try:
        if obj is None:
            return False
        fill_attr = getattr(obj, "fill", None)
        compute_attr = getattr(obj, "compute", None)
        return callable(fill_attr) and callable(compute_attr)
    except Exception:
        return False

def difference(d1, d2, level=-1):
    """Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.  See :func:`intersection`
    for more details.

    *d1* and *d2* remain unchanged.  However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.
    """
    if not isinstance(d1, dict) or not isinstance(d2, dict):
        raise TypeError("both d1 and d2 must be dictionaries")

    def _diff(sub1, sub2, rem_depth):
        out = {}
        for k, v1 in sub1.items():
            if k not in sub2:
                # Key only in d1
                out[k] = v1
                continue
            v2 = sub2[k]
            if v1 == v2:
                continue  # identical, no difference
            if isinstance(v1, dict) and isinstance(v2, dict):
                # Recursion allowed?
                if rem_depth == 0:
                    out[k] = v1
                else:
                    child = _diff(v1, v2, rem_depth - 1 if rem_depth > 0 else -1)
                    if child:  # only add if child is non‑empty
                        out[k] = child
            else:
                out[k] = v1
        return out

    return _diff(d1, d2, level)

def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    """Together with :func:``generate_default_observer_schema_list``, this function is
    called recursively to generate part of a default ``observer_schema`` from part of a
    Kubernetes resource, defined respectively by ``manifest_dict`` or ``manifest_list``.

    Args:
        manifest_dict (dict): Partial Kubernetes resources
        first_level (bool, optional): If True, indicates that the dictionary represents
            the whole observer schema of a Kubernetes resource

    Returns:
        dict: Generated partial observer_schema

    This function creates a new dictionary from ``manifest_dict`` and replaces all
    non-list and non-dict values by ``None``.

    In case of ``first_level`` dictionary (i.e. complete ``observer_schema`` for a
    resource), the values of the identifying fields are copied from the manifest file.

    """
    if not isinstance(manifest_dict, dict):
        return None

    # Identify fields that should be preserved when creating a top‑level observer schema
    IDENTIFYING_FIELDS = {"apiVersion", "kind", "metadata"}

    result = {}
    for key, value in manifest_dict.items():
        if isinstance(value, dict):
            # Recurse into nested dictionaries
            result[key] = generate_default_observer_schema_dict(value, first_level=False)
        elif isinstance(value, list):
            # Process each element of a list, preserving nested dicts
            processed_list = []
            for item in value:
                if isinstance(item, dict):
                    processed_list.append(generate_default_observer_schema_dict(item, first_level=False))
                else:
                    processed_list.append(None)
            result[key] = processed_list
        else:
            # For scalar values, keep the original if this is the first level
            # and the key is one of the identifying fields; otherwise set to None
            if first_level and key in IDENTIFYING_FIELDS:
                result[key] = value
            else:
                result[key] = None
    return result

def update_last_applied_manifest_list_from_resp(
    last_applied_manifest, observer_schema, response
):
    """Together with :func:``update_last_applied_manifest_dict_from_resp``, this
    function is called recursively to update a partial ``last_applied_manifest``
    from a partial Kubernetes response

    Args:
        last_applied_manifest (list): partial ``last_applied_manifest`` being
            updated
        observer_schema (list): partial ``observer_schema``
        response (list): partial response from the Kubernetes API.

    This function go through all observed fields, and initialized their value in
    last_applied_manifest if they are not yet present

    """
    # Basic validation
    if not isinstance(observer_schema, list):
        raise TypeError("observer_schema must be a list, got %r" % observer_schema)
    if not isinstance(response, list):
        raise TypeError("response must be a list, got %r" % response)

    # Ensure last_applied_manifest is mutable and starts as a list
    if last_applied_manifest is None:
        last_applied_manifest = []

    # If the observer_schema contains a dictionary, it represents nested fields.
    for schema_item in observer_schema:
        try:
            # Handle nested schema represented as a dict: {key: sub_schema}
            if isinstance(schema_item, dict):
                for key, sub_schema in schema_item.items():
                    # Find the corresponding item in response with this key
                    resp_item = next(
                        (item for item in response if item.get("key") == key), None
                    )
                    if resp_item is None:
                        continue  # No data for this key in the response
                    # Ensure there is a corresponding entry in last_applied_manifest
                    manifest_item = next(
                        (item for item in last_applied_manifest if item.get("key") == key),
                        None,
                    )
                    if manifest_item is None:
                        # Create a new entry with key and empty value
                        manifest_item = {"key": key}
                        last_applied_manifest.append(manifest_item)
                    # Recurse on the nested structure
                    if isinstance(sub_schema, list) and isinstance(resp_item.get("value"), list):
                        # Recursively update nested list
                        update_last_applied_manifest_list_from_resp(
                            manifest_item.get("value", []),
                            sub_schema,
                            resp_item["value"],
                        )
                    else:
                        # If the value is not a list, just set it if not already set
                        if manifest_item.get("value") is None:
                            manifest_item["value"] = resp_item.get("value")
            else:
                # Handle simple key/value schema: the item is a key string
                key = schema_item
                # Find the response item with this key
                resp_item = next(
                    (item for item in response if item.get("key") == key), None
                )
                if resp_item is None:
                    continue
                # Find or create the entry in last_applied_manifest
                manifest_item = next(
                    (item for item in last_applied_manifest if item.get("key") == key),
                    None,
                )
                if manifest_item is None:
                    manifest_item = {"key": key}
                    last_applied_manifest.append(manifest_item)
                # Set value if not already present
                if manifest_item.get("value") is None:
                    manifest_item["value"] = resp_item.get("value")
        except Exception as exc:
            # Log or re-raise with context if needed
            raise RuntimeError(
                f"Error while updating last_applied_manifest for schema_item {schema_item}: {exc}"
            ) from exc
    return last_applied_manifest

def update_last_applied_manifest_dict_from_resp(
    last_applied_manifest, observer_schema, response
):
    """Together with :func:``update_last_applied_manifest_list_from_resp``, this
    function is called recursively to update a partial ``last_applied_manifest``
    from a partial Kubernetes response

    Args:
        last_applied_manifest (dict): partial ``last_applied_manifest`` being
            updated
        observer_schema (dict): partial ``observer_schema``
        response (dict): partial response from the Kubernetes API.

    Raises:
        KeyError: If the observed field is not present in the Kubernetes response

    This function go through all observed fields, and initialized their value in
    last_applied_manifest if they are not yet present

    """
    # Ensure that the provided parameters are dictionary-like
    if not isinstance(last_applied_manifest, dict):
        raise TypeError(
            f"last_applied_manifest must be a dict, got {type(last_applied_manifest)}"
        )
    if not isinstance(observer_schema, dict):
        raise TypeError(
            f"observer_schema must be a dict, got {type(observer_schema)}"
        )
    if not isinstance(response, dict):
        raise TypeError(
            f"response must be a dict, got {type(response)}"
        )

    for field, sub_schema in observer_schema.items():
        # Verify the field exists in the response
        if field not in response:
            raise KeyError(
                f"Observed field '{field}' not present in Kubernetes response"
            )

        # If the sub_schema is a dict, we recurse into the nested dictionary
        if isinstance(sub_schema, dict):
            resp_value = response[field]
            if not isinstance(resp_value, dict):
                # The schema expects a dict but the response gives something else
                raise KeyError(
                    f"Expected dict for field '{field}' but got {type(resp_value)}"
                )
            # Get or create the nested dict in the manifest
            nested_manifest = last_applied_manifest.setdefault(field, {})
            if not isinstance(nested_manifest, dict):
                # Something went wrong with the existing manifest
                raise TypeError(
                    f"Existing manifest entry for '{field}' is not a dict"
                )
            # Recurse
            update_last_applied_manifest_dict_from_resp(
                nested_manifest, sub_schema, resp_value
            )
        else:
            # Simple leaf field: set only if not already present
            if field not in last_applied_manifest:
                last_applied_manifest[field] = response[field]

    return last_applied_manifest

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    # Defensive checks for required attributes
    if app is None:
        raise ValueError("app cannot be None")
    spec = getattr(app, "spec", None)
    if spec is None:
        raise AttributeError("app has no 'spec' attribute")
    manifest = getattr(spec, "manifest", None)
    if not isinstance(manifest, dict):
        # Nothing to process if manifest is missing or not a dict
        return

    # Ensure there is a place to store observer schemas
    observer_schema_map = getattr(spec, "observer_schema", None)
    if observer_schema_map is None:
        observer_schema_map = {}
        # If spec is a mutable object, set attribute back
        if hasattr(spec, "__dict__"):
            spec.observer_schema = observer_schema_map
    if not isinstance(observer_schema_map, dict):
        # If spec.observer_schema exists but is not a dict, raise to avoid silent bug
        raise TypeError("app.spec.observer_schema must be a dict")

    # Iterate over all resources in manifest
    for res_name, res_def in manifest.items():
        # Skip if a custom observer schema already exists
        if res_name in observer_schema_map:
            continue
        # Create a simple default schema
        # A minimal schema for a Kubernetes resource typically has at least the 'metadata' field
        default_schema = {
            "type": "object",
            "properties": {
                "metadata": {"type": "object"},
                "spec": {"type": "object"},
                "status": {"type": "object"},
            },
            "required": ["metadata"],
        }
        observer_schema_map[res_name] = default_schema
    # Nothing is returned; the method updates the application's spec in place.

def status_str(self, prefix=''):
    """Return string representation of validation log, with optional prefix."""
    # Try to get the log object; raise an informative error if missing.
    try:
        log_obj = getattr(self, 'log')
    except AttributeError:
        return ''

    # If the log itself is a string, return it prefixed.
    if isinstance(log_obj, str):
        return prefix + log_obj

    # If the log is a dict-like object that can be stringified.
    if isinstance(log_obj, dict):
        try:
            return prefix + str(log_obj)
        except Exception:
            return ''

    # If the log is an iterable of items (list, tuple, set, etc.).
    if hasattr(log_obj, '__iter__') and not isinstance(log_obj, (bytes, bytearray, str)):
        lines = []
        for item in log_obj:
            # Prefer a "message" attribute if it exists.
            if isinstance(item, dict):
                text = item.get('message', str(item))
            elif hasattr(item, 'message'):
                text = str(item.message)
            else:
                text = str(item)

            lines.append(f"{prefix}{text}")

        return '\n'.join(lines)

    # Fallback: convert to string directly.
    try:
        return prefix + str(log_obj)
    except Exception:
        # If conversion fails, return an empty string.
        return ''

def validate(self, inventory, extract_spec_version=False):
    """Validate a given inventory.

    If extract_spec_version is True then will look at the type value to determine
    the specification version. In the case that there is no type value or it isn't
    valid, then other tests will be based on the version given in self.spec_version.
    """
    # Basic type check of the inventory
    if not isinstance(inventory, (dict, list)):
        raise ValueError("Inventory must be a dict or a list")

    # Determine which spec version to use
    spec_version = getattr(self, "spec_version", None)
    if spec_version is None:
        raise ValueError("self.spec_version is not set")

    if extract_spec_version:
        # Helper to extract a version string from an item
        def _get_version_from_item(item):
            if not isinstance(item, dict):
                return None
            t = item.get("type")
            if not isinstance(t, str):
                return None
            # Allow simple patterns like 'v1', 'v2', etc.
            if t.startswith("v") and t[1:].isdigit():
                return t
            return None

        # Iterate over the first-level items
        if isinstance(inventory, dict):
            candidates = inventory.values()
        else:
            candidates = inventory

        for itm in candidates:
            ver = _get_version_from_item(itm)
            if ver is not None:
                spec_version = ver
                break  # use the first valid type found

    # Delegate to a lower‑level validator if one exists
    try:
        if hasattr(self, "_validate_inventory"):
            return self._validate_inventory(inventory, spec_version)
        # If no private validator exists, consider the inventory valid
        return True
    except Exception as exc:
        # Wrap any exception that bubbled up from the validation logic
        raise ValueError(f"Inventory validation failed: {exc}") from exc

def validate_as_prior_version(self, prior):
    """Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    if prior is None:
        return
    if not isinstance(prior, self.__class__):
        raise TypeError(
            f'prior must be an instance of {self.__class__.__name__}, got {type(prior)}'
        )

    # Check that prior species and parameters are subsets of current inventory
    prior_species = set(prior.species)
    current_species = set(self.species)
    missing_species = prior_species - current_species
    if missing_species:
        raise ValueError(
            f'Current inventory is missing species from prior: {missing_species}'
        )

    prior_params = set(prior.parameters)
    current_params = set(self.parameters)
    missing_params = prior_params - current_params
    if missing_params:
        raise ValueError(
            f'Current inventory is missing parameters from prior: {missing_params}'
        )

    # Ensure current inventory contains at least the same number of reactions
    if len(self.propensities) < len(prior.propensities):
        raise ValueError(
            'Current inventory has fewer reactions than prior '
            f'({len(self.propensities)} vs {len(prior.propensities)})'
        )

    # Verify that each reaction in the prior matches the corresponding one
    # in the current inventory (by position).  Additional reactions are
    # permitted, but existing ones must remain unchanged.
    for idx, prior_prop in enumerate(prior.propensities):
        curr_prop = self.propensities[idx]
        if curr_prop != prior_prop:
            raise ValueError(
                f'Reaction at index {idx} changed from {prior_prop} to {curr_prop}'
            )

    # Basic checks on the stoichiometry matrices
    if self.stoichiometry_matrix.rows != len(self.species):
        raise ValueError(
            f'Stoichiometry matrix rows {self.stoichiometry_matrix.rows} '
            f'don\'t match number of species {len(self.species)}'
        )
    if prior.stoichiometry_matrix.rows != len(prior.species):
        raise ValueError(
            f'Prior stoichiometry matrix rows {prior.stoichiometry_matrix.rows} '
            f'don\'t match number of prior species {len(prior.species)}'
        )
    if self.stoichiometry_matrix.cols < prior.stoichiometry_matrix.cols:
        raise ValueError(
            'Current inventory has fewer reaction columns than prior: '
            f'{self.stoichiometry_matrix.cols} vs {prior.stoichiometry_matrix.cols}'
        )

    # Map species indices to compare stoichiometry values for common species
    current_index = {s: i for i, s in enumerate(self.species)}
    prior_index = {s: i for i, s in enumerate(prior.species)}

    # Compare every species that existed in the prior; reactions may be added.
    for p_spec, p_row in prior_index.items():
        c_row = current_index[p_spec]
        for j in range(prior.stoichiometry_matrix.cols):
            prior_val = prior.stoichiometry_matrix[p_row, j]
            # Missing columns in the current matrix are treated as zero
            curr_val = (
                self.stoichiometry_matrix[c_row, j]
                if j < self.stoichiometry_matrix.cols
                else 0
            )
            if prior_val != curr_val:
                raise ValueError(
                    f'Stoichiometry mismatch for species {p_spec} '
                    f'and reaction column {j}: {prior_val} vs {curr_val}'
                )

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may include references to duplicate files in
    later versions than the version being described.
    """
    # Basic validation
    if not isinstance(inventory, dict):
        raise TypeError("inventory must be a dictionary mapping logical paths to version mappings")
    # Normalise the target version for comparison
    if isinstance(version, str) and version.lower() == "latest":
        target_version = None
    else:
        try:
            target_version = float(version) if isinstance(version, (int, float)) else float(version)
        except Exception:  # pragma: no cover
            raise ValueError("version must be convertible to a float or the string \"latest\"")
    result = {}
    # Pre‑compute the maximum version if needed
    if target_version is None:
        max_version = None
        for ver_map in inventory.values():
            if isinstance(ver_map, dict):
                for ver_key in ver_map:
                    try:
                        ver_num = float(ver_key) if isinstance(ver_key, (int, float)) else float(ver_key)
                    except Exception:
                        continue
                    if max_version is None or ver_num > max_version:
                        max_version = ver_num
            elif hasattr(ver_map, "__iter__"):
                for pair in ver_map:
                    try:
                        ver_key, _ = pair
                        ver_num = float(ver_key) if isinstance(ver_key, (int, float)) else float(ver_key)
                    except Exception:
                        continue
                    if max_version is None or ver_num > max_version:
                        max_version = ver_num
        target_version = max_version
    # Iterate over the logical paths
    for logical_path, ver_map in inventory.items():
        if not logical_path:
            continue
        fileset = set()
        if isinstance(ver_map, dict):
            items = ver_map.items()
        elif hasattr(ver_map, "__iter__"):
            items = ver_map
        else:
            continue
        for ver_key, content_file in items:
            try:
                ver_num = float(ver_key) if isinstance(ver_key, (int, float)) else float(ver_key)
            except Exception:
                continue
            # Include files that belong to the requested version or later
            if ver_num >= target_version:
                fileset.add(content_file)
        if fileset:
            result[logical_path] = fileset
    return result

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    # Ensure fixity is a dictionary
    if not isinstance(fixity, dict):
        raise ValueError("Fixity block must be a dictionary")

    # The fixity block must contain a 'files' key
    if 'files' not in fixity:
        raise ValueError("Fixity block missing required 'files' key")

    files = fixity['files']

    # The 'files' value must be an iterable (list/tuple/etc)
    if not isinstance(files, (list, tuple)):
        raise ValueError("'files' in fixity block must be a list or tuple")

    # Convert manifest_files to a set for fast lookup if it isn't already
    if not isinstance(manifest_files, (set, list, tuple)):
        raise ValueError("manifest_files must be an iterable of file identifiers")

    manifest_set = set(manifest_files)

    # Validate each referenced file
    for candidate in files:
        if candidate not in manifest_set:
            raise ValueError(
                f"File '{candidate}' referenced in fixity block not found in the manifest"
            )

def files_list(path):
    """Return the files in `path`"""

    import os

    if not os.path.exists(path):
        raise FileNotFoundError(path)

    abs_path = os.path.abspath(path)

    if os.path.isfile(abs_path) or os.path.islink(abs_path):
        return [abs_path]

    if os.path.isdir(abs_path):
        files = []
        for root, _, filenames in os.walk(abs_path, topdown=True):
            for fname in filenames:
                files.append(os.path.join(root, fname))
        return files

    # In case the path is something else (e.g., a device), treat as a file
    return [abs_path]

def _explore_folder(folder):
    """
    Get packages' data from folder

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    folder : str
        Folder of the package
    Returns
    -------
    dict
    """
    import os

    if not isinstance(folder, str):
        raise TypeError(f"folder must be a string, got {type(folder).__name__}")

    if not os.path.isdir(folder):
        raise ValueError(f"Provided path '{folder}' is not a directory or does not exist")

    packages = {}

    # First pass: locate all XML files to identify package basenames
    try:
        for root, _, files in os.walk(folder):
            for filename in files:
                if filename.lower().endswith('.xml'):
                    base = os.path.splitext(filename)[0]
                    xml_path = os.path.join(root, filename)
                    packages[base] = {'xml': xml_path, 'files': []}
    except OSError as e:
        raise RuntimeError(f"Error accessing files in '{folder}': {e}") from e

    # Second pass: gather all files that share the XML basename
    if not packages:
        return packages  # No XML files found

    try:
        xml_basenames = set(packages.keys())
        for root, _, files in os.walk(folder):
            for filename in files:
                base = os.path.splitext(filename)[0]
                if base in xml_basenames:
                    packages[base]['files'].append(os.path.join(root, filename))
    except OSError as e:
        raise RuntimeError(f"Error accessing files in '{folder}': {e}") from e

    return packages

def _explore_zipfile(zip_path):
    """Get packages' data from zip_path

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    zip_path : str
        zip file path
    Returns
    -------
    dict
        Mapping from XML basename to another dict containing each file
        path (relative to the archive) as key and its content as bytes.
    """
    import os
    import zipfile

    # Validate input
    if not isinstance(zip_path, str):
        raise TypeError("zip_path must be a string")
    if not os.path.isfile(zip_path):
        raise FileNotFoundError(f"File not found: {zip_path}")

    packages = {}
    try:
        with zipfile.ZipFile(zip_path, 'r') as zin:
            for zinfo in zin.infolist():
                if zinfo.is_dir():
                    continue
                # Read file content
                try:
                    data = zin.read(zinfo)
                except Exception as exc:
                    # Skip unreadable entries but allow processing to continue
                    continue

                # Determine XML basename (if present)
                base_name = None
                filename = os.path.basename(zinfo.filename)
                name_part, ext = os.path.splitext(filename)
                if ext.lower() == ".xml":
                    base_name = name_part

                if base_name is not None:
                    # Group under the base_name
                    if base_name not in packages:
                        packages[base_name] = {}
                    packages[base_name][zinfo.filename] = data
                else:
                    # Attempt to associate non-XML file with an existing package
                    # based on the directory structure: if the file shares the same
                    # directory prefix, assign it to the first matching package if any.
                    dir_prefix = os.path.dirname(zinfo.filename)
                    matched = None
                    for pkg in packages:
                        if dir_prefix.startswith(pkg):
                            matched = pkg
                            break
                    if matched:
                        packages[matched][zinfo.filename] = data

    except zipfile.BadZipFile as exc:
        raise zipfile.BadZipFile(f"Invalid zip file: {zip_path}") from exc
    except Exception as exc:
        # Catch any other runtime errors that might occur during processing
        raise RuntimeError(f"Error while exploring zip file '{zip_path}': {exc}") from exc

    return packages

def fix_namespace_prefix_w(content):
    """Convert os textos cujo padrão é `w:st="` em `w-st="`."""
    if not isinstance(content, str):
        return content
    try:
        return content.replace('w:st="', 'w-st="')
    except Exception:
        # If replacement fails for some reason, just return the original content
        return content

def match_pubdate(node, pubdate_xpaths):
    """
    Retorna o primeiro match da lista de pubdate_xpaths
    """
    for xpath in pubdate_xpaths:
        try:
            matches = node.xpath(xpath)
            if matches:
                first = matches[0]
                # If it's an element, return its text content, otherwise return the result itself
                return first.text if hasattr(first, "text") else first
        except Exception:
            # Skip invalid xpath expressions or other xpath-related errors
            continue
    return None

def pretty(self, indent=0, debug=False):
    """Return a pretty formatted representation of self."""
    # Validate indent argument
    if not isinstance(indent, int) or indent < 0:
        raise ValueError("indent must be a non‑negative integer")

    # Try to obtain a suitable string representation
    try:
        representation = str(self)
    except Exception:
        # Fallback to repr if str fails
        representation = repr(self)

    # Apply indentation to each line if requested
    if indent > 0:
        ind = " " * indent
        representation = "\n".join(ind + line for line in representation.splitlines())

    # If debug mode is requested, add type information
    if debug:
        try:
            type_info = f"<type: {type(self).__qualname__} at {hex(id(self))}>"
            representation = f"{representation}\n{type_info}"
        except Exception:
            # Ignore any errors while adding debug info
            pass

    return representation

def tzname_in_python2(namefunc):
    """Change unicode output into bytestrings in Python 2

    tzname() API changed in Python 3. It used to return bytes, but was changed
    to unicode strings
    """
    if not callable(namefunc):
        raise TypeError("The argument 'namefunc' must be callable")
    try:
        # If the 'unicode' type exists, we are running under Python 2
        unicode
        py2 = True
    except NameError:
        py2 = False

    def wrapped(*args, **kwargs):
        result = namefunc(*args, **kwargs)
        if py2:
            # In Python 2, strings are bytes; unicode strings need encoding
            if isinstance(result, str):
                return result
            else:
                return result.encode()
        else:
            return result

    return wrapped

def get_versions():
    """Get version information or return default if unable to do so."""
    default = "unknown"
    try:
        # Attempt to read a version from a predefined VERSION_PATH
        with open(VERSION_PATH, "r", encoding="utf-8") as f:
            content = f.read()
        for line in content.splitlines():
            if "=" in line:
                key, value = line.split("=", 1)
                key, value = key.strip(), value.strip()
                # Strip surrounding quotes if present
                if value and ((value[0] == value[-1] and value[0] in ("'", "\""))):
                    value = value[1:-1]
                if value:
                    return value
    except Exception:
        # Either VERSION_PATH is not defined, file missing, or parsing failed
        pass

    try:
        # Fallback: try to obtain the version via importlib.metadata
        import importlib.metadata
        pkg_name = __package__
        if not pkg_name:
            # If we cannot determine the package name, use distribution name fallback
            return default
        return importlib.metadata.version(pkg_name)
    except Exception:
        pass

    # If all attempts fail, return the supplied default
    return default

def plus_or_dot(pieces):
    """Return a + if we don't already have one, else return a ."""
    try:
        # Evaluate whether a plus sign is already present in the collection.
        return '.' if '+' in pieces else '+'
    except Exception:
        # If pieces is not iterable or any other error occurs, assume no plus present.
        return '+'

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    import subprocess
    import shlex

    # Validate the command(s)
    if isinstance(commands, str):
        cmd_list = [commands]
    elif isinstance(commands, (list, tuple)):
        cmd_list = list(commands)
    else:
        raise TypeError(f"commands must be str or list/tuple, got {type(commands).__name__}")

    # Validate and process args
    if args is None:
        args_list = []
    elif isinstance(args, str):
        # If args is a string, split it for safety
        args_list = shlex.split(args)
    elif isinstance(args, (list, tuple)):
        args_list = list(args)
    else:
        raise TypeError(f"args must be None, str, or list/tuple, got {type(args).__name__}")

    # Final command
    full_cmd = cmd_list + args_list

    if not full_cmd:
        raise ValueError("No command specified")

    # Log command if verbose
    if verbose:
        import pprint
        print("Running command:", pprint.pformat(full_cmd))
        if cwd:
            print("Working directory:", cwd)
        if env:
            print("Environment variables:", env)

    # Set stderr handling
    stderr_opt = subprocess.DEVNULL if hide_stderr else None

    try:
        result = subprocess.run(
            full_cmd,
            cwd=cwd,
            env=env,
            stdout=subprocess.PIPE,
            stderr=stderr_opt,
            text=True,
            check=True,  # raise CalledProcessError on non-zero exit
        )
        return result
    except FileNotFoundError as e:
        raise RuntimeError(f"Command not found: {full_cmd[0]}") from e
    except subprocess.CalledProcessError as e:
        # Return the CompletedProcess with returncode and output
        return e
    except Exception as e:
        raise RuntimeError(f"Failed to run command: {full_cmd}") from e

def register_vcs_handler(vcs, method):
    """Create decorator to mark a method as the handler of a VCS."""
    def decorator(f):
        """Store f in HANDLERS[vcs][method]."""
        if not isinstance(vcs, str):
            raise TypeError("vcs must be a string")
        if not isinstance(method, str):
            raise TypeError("method must be a string")
        if vcs not in HANDLERS:
            HANDLERS[vcs] = {}
        HANDLERS[vcs][method] = f
        return f
    return decorator

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    # Basic type checks for parameters
    if not isinstance(validate_objects, bool):
        raise TypeError(f"'validate_objects' must be a bool, got {type(validate_objects).__name__}")
    if not isinstance(check_digests, bool):
        raise TypeError(f"'check_digests' must be a bool, got {type(check_digests).__name__}")
    if not isinstance(show_warnings, bool):
        raise TypeError(f"'show_warnings' must be a bool, got {type(show_warnings).__name__}")

    # Helper to recursively iterate over objects in the hierarchy
    def _iter_objects(root):
        stack = [root]
        visited = set()
        while stack:
            obj = stack.pop()
            obj_id = id(obj)
            if obj_id in visited:
                continue
            visited.add(obj_id)
            yield obj
            # Attempt to find sub-objects via common container attributes
            try:
                # If the object has a 'children' attribute, iterate over it
                children = getattr(obj, 'children', None)
                if isinstance(children, (list, tuple)):
                    stack.extend(children)
                elif isinstance(children, dict):
                    stack.extend(children.values())
            except Exception:
                pass
            # Inspect all attributes that might be objects
            for attr in getattr(obj, '__dict__', {}):
                try:
                    val = getattr(obj, attr)
                except Exception:
                    continue
                if isinstance(val, (list, tuple)):
                    for item in val:
                        if hasattr(item, '__dict__'):
                            stack.append(item)
                elif isinstance(val, dict):
                    for item in val.values():
                        if hasattr(item, '__dict__'):
                            stack.append(item)
                elif hasattr(val, '__dict__'):
                    stack.append(val)

    # Determine the root(s) of the hierarchy
    roots = []
    if hasattr(self, 'storage_root'):
        roots.append(self.storage_root)
    elif hasattr(self, 'root'):
        roots.append(self.root)
    else:
        # Fall back to the instance itself as root
        roots.append(self)

    num_objects = 0
    good_objects = 0

    for root in roots:
        for obj in _iter_objects(root):
            if obj is None:
                continue
            num_objects += 1
            # Skip objects that do not support validation or digest checks
            if not validate_objects and not check_digests:
                good_objects += 1
                continue
            obj_valid = True
            # Validate object if validate_objects
            if validate_objects and hasattr(obj, 'validate'):
                try:
                    result = obj.validate()
                    if result is False:
                        obj_valid = False
                except Exception as exc:
                    obj_valid = False
                    if show_warnings:
                        print(f"Warning: validation failed for {obj} (exception: {exc})")
            # Check digest if requested
            if check_digests and hasattr(obj, 'check_digest'):
                try:
                    digest_ok = obj.check_digest()
                    if not digest_ok:
                        obj_valid = False
                except Exception as exc:
                    obj_valid = False
                    if show_warnings:
                        print(f"Warning: digest check failed for {obj} (exception: {exc})")
            if obj_valid:
                good_objects += 1
            elif show_warnings:
                print(f"Warning: object {obj} failed validation checks.")

    return num_objects, good_objects

def validate_version_inventories(self, version_dirs):
        """Each version SHOULD have an inventory up to that point.

        Also keep a record of any content digests different from those in the root inventory
        so that we can also check them when validating the content.

        version_dirs is an array of version directory names and is assumed to be in
        version sequence (1, 2, 3...).
        """
        # Basic validation of input
        if not isinstance(version_dirs, (list, tuple)):
            raise TypeError("version_dirs must be an iterable list or tuple of directory names")
        if not all(isinstance(d, str) and d for d in version_dirs):
            raise ValueError("All items in version_dirs must be non-empty strings")

        # Prepare containers for root inventory and differences
        root_inventory = None
        # self.different_digests should be a dict mapping file -> set of version dirs where digest differs
        if not hasattr(self, "different_digests"):
            self.different_digests = {}

        for idx, vdir in enumerate(version_dirs):
            inv_path = os.path.join(vdir, "inventory.json")
            if not os.path.exists(inv_path):
                raise ValueError(f"Missing inventory file in version directory '{vdir}': expected '{inv_path}'")

            try:
                with open(inv_path, "r", encoding="utf-8") as fh:
                    inventory = json.load(fh)
            except Exception as exc:
                raise ValueError(f"Could not load inventory.json from '{vdir}': {exc}") from exc

            if not isinstance(inventory, dict):
                raise ValueError(f"Inventory in '{vdir}' must be a JSON object mapping files to digests")

            # Set the first inventory as the root if not already set
            if root_inventory is None:
                root_inventory = inventory
                continue

            # Compare current inventory against the root
            for file_path, digest in inventory.items():
                root_digest = root_inventory.get(file_path)
                if root_digest != digest:
                    self.different_digests.setdefault(file_path, set()).add(vdir)

            # Additionally, check for new files present only in the current inventory
            for file_path in set(inventory.keys()) - set(root_inventory.keys()):
                self.different_digests.setdefault(file_path, set()).add(vdir)

        # If we encountered any differences, we keep them in `self.different_digests`
        # Return self for potential chaining
        return self

def amend_bzparams(self, params, bug_ids):
    """Amend the Bugzilla params

    Add a list of bug IDs to the request parameters for a Bugzilla API call.
    Accepts an integer, string, or any iterable of integers/strings.
    Existing ``ids`` values are preserved and concatenated with the new ones.
    Raises :class:`TypeError` if the supplied ``bug_ids`` is not an int,
    string, or iterable of those types.
    """
    if params is None or not isinstance(params, dict):
        raise ValueError("params must be a dictionary")

    if bug_ids is None:
        return params

    # Convert bug_ids to a comma‑separated string
    if isinstance(bug_ids, (int, str)):
        ids_str = str(bug_ids)
    elif isinstance(bug_ids, (list, tuple, set)):
        try:
            ids_str = ",".join(str(i) for i in bug_ids)
        except Exception as e:
            raise TypeError("bug_ids must consist of ints or strings") from e
    else:
        raise TypeError("bug_ids must be an int, string, or iterable of those types")

    if not ids_str:
        return params  # nothing to add

    # Merge with any existing ids value
    existing = params.get("ids")
    if existing:
        if isinstance(existing, str):
            existing_ids = [part.strip() for part in existing.split(",") if part.strip()]
        else:
            existing_ids = [str(e) for e in existing]
        combined = ",".join(existing_ids + [ids_str])
        params["ids"] = combined
    else:
        params["ids"] = ids_str

    return params

def deep_merge_nodes(nodes):
    '''
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.
    '''
    def _is_mapping(node):
        return getattr(node, 'tag', None) == 'tag:yaml.org,2002:map'

    def _merge_mapping(existing, new):
        """Recursively merge two MappingNode children."""
        existing_list = existing.value
        new_list = new.value
        # Build a key -> (key_node, value_node) mapping from existing
        merged_dict = {}
        key_order = []
        for k_node, v_node in existing_list:
            key = k_node.value
            merged_dict[key] = (k_node, v_node)
            key_order.append(key)
        # Merge new items
        for k_node, v_node in new_list:
            key = k_node.value
            if key in merged_dict:
                old_k, old_v = merged_dict[key]
                if _is_mapping(old_v) and _is_mapping(v_node):
                    merged_v = _merge_mapping(old_v, v_node)
                    merged_dict[key] = (old_k, merged_v)
                else:
                    merged_dict[key] = (old_k, v_node)
            else:
                merged_dict[key] = (k_node, v_node)
                key_order.append(key)
        # Preserve order: existing order first, then new keys appended
        merged_list = [merged_dict[key] for key in key_order]
        return type(existing)(tag=existing.tag, value=merged_list)

    result = []
    seen = {}
    order_keys = []

    for key_node, value_node in nodes:
        key = key_node.value
        if key in seen:
            old_key_node, old_value_node = seen[key]
            if _is_mapping(old_value_node) and _is_mapping(value_node):
                merged_value = _merge_mapping(old_value_node, value_node)
                seen[key] = (old_key_node, merged_value)
            else:
                seen[key] = (old_key_node, value_node)
        else:
            seen[key] = (key_node, value_node)
            order_keys.append(key)

    for k in order_keys:
        result.append(seen[k])
    return result

def parse_arguments(*arguments):
    """
    Given command-line arguments with which this script was invoked, parse the arguments and
    return them as an ArgumentParser instance (i.e. the resulting Namespace object).
    """
    import argparse
    parser = argparse.ArgumentParser()
    if arguments:
        return parser.parse_args(list(arguments))
    return parser.parse_args()

def parser_flags(parser):
    """Given an argparse.ArgumentParser instance, return its argument flags in a space-separated string."""
    if parser is None:
        raise ValueError("parser cannot be None")
    # Try to access the internal list of actions; if not available, raise an error.
    try:
        actions = parser._actions
    except AttributeError:
        raise TypeError("Expected an argparse.ArgumentParser instance")
    flags = []
    for action in actions:
        # action.option_strings is a list of flag strings (e.g., ['-v', '--verbose'])
        for opt in getattr(action, 'option_strings', []):
            if opt and opt not in flags:
                flags.append(opt)
    return ' '.join(flags)

def parser_flags(parser):
    """
    Given an argparse.ArgumentParser instance, return its argument flags in a space‑separated string.
    """
    if parser is None:
        raise TypeError("parser argument cannot be None")
    flags = []
    for action in getattr(parser, "_actions", []):
        option_strings = getattr(action, "option_strings", None)
        if option_strings:
            flags.extend(option_strings)
    # Preserve order but remove duplicates
    seen = set()
    unique_flags = []
    for flag in flags:
        if flag not in seen:
            seen.add(flag)
            unique_flags.append(flag)
    return " ".join(unique_flags)

def bash_completion():
    """
    Return a bash completion script for the borgmatic command. Produce this by introspecting
    borgmatic's command-line argument parsers.
    """
    try:
        import borgmatic.cli.main as bm_main
        import click
        # borgmatic uses click; the root Group is usually named `main`
        root_cmd = getattr(bm_main, "main", None)
        if root_cmd is None:
            return "# Unable to locate borgmatic command group.\n"
        # Obtain the Click shell completion helper for bash
        try:
            # Click 8.1+ provides `get_bash_complete_script`
            from click.shell_completion import get_bash_complete_script
            script = get_bash_complete_script(root_cmd, root_cmd.name)
            if script:
                return script
        except ImportError:
            pass
        # Fallback: construct a minimal script using Click's internal method
        try:
            # older Click versions expose `shell_completion` with `bash` method
            script = click.shell_completion.bash(root_cmd, root_cmd.name)
            if script:
                return script
        except Exception:
            pass
        # If all methods fail, return a placeholder
        return "# Bash completion script could not be generated automatically.\n"
    except Exception as exc:
        return f"# Error generating bash completion script: {exc}\n"

def parse_subparser_arguments(unparsed_arguments, subparsers):
    """
    Given a sequence of arguments and a dict from subparser name to argparse.ArgumentParser
    instance, give each requested action's subparser a shot at parsing all arguments. This
    allows common arguments like "--repository" to be shared across multiple subparsers.

    Return the result as a tuple of (a dict mapping from subparser name to a parsed
    namespace of arguments, a list of remaining arguments not claimed by any subparser).
    """
    if not isinstance(subparsers, dict):
        raise TypeError("subparsers must be a dict mapping names to ArgumentParser instances")
    if not isinstance(unparsed_arguments, (list, tuple)):
        raise TypeError("unparsed_arguments must be a list or tuple of strings")

    parsed_namespaces = {}
    claimed = set()

    for name, parser in subparsers.items():
        if parser is None:
            continue
        try:
            namespace, unknown = parser.parse_known_args(list(unparsed_arguments))
        except Exception:
            # If a parser fails to parse, skip it but leave the arguments untouched
            continue
        parsed_namespaces[name] = namespace
        # Arguments that this parser claimed are those not in the unknown list
        claimed.update(set(unparsed_arguments) - set(unknown))

    # Remaining arguments are those that were not claimed by any subparser
    remaining = [arg for arg in unparsed_arguments if arg not in claimed]

    return parsed_namespaces, remaining

def _dictsum(dicts):
    """
    Combine values of the dictionaries supplied by iterable dicts.

    >>> _dictsum([{'a': 1, 'b': 2}, {'a': 5, 'b': 0}])
    {'a': 6, 'b': 2}
    """
    totals = {}
    for d in dicts:
        if not isinstance(d, dict):
            raise TypeError(f"Expected dict, got {type(d).__name__}")
        for key, value in d.items():
            if not isinstance(value, (int, float, complex)):
                raise TypeError(
                    f"Value for key {key!r} must be numeric, got {type(value).__name__}"
                )
            totals[key] = totals.get(key, 0) + value
    return totals}

def _replace_url_args(url, url_args):
    """Replace any custom string URL items with values in args"""

    # Ensure the URL is a string
    if not isinstance(url, str):
        return ''

    # If no arguments to replace, return original URL
    if not isinstance(url_args, dict) or not url_args:
        # The following substitution will be skipped naturally
        return url

    # Pattern to find placeholders in the form {name}
    pattern = r'\{([^}]+)\}'

    # Replacement function
    def _sub(match):
        key = match.group(1)
        if key not in url_args:
            # If no value provided, keep placeholder unchanged
            return match.group(0)
        value = url_args[key]
        if value is None:
            value = ''
        # Convert to string and URL‑encode
        try:
            from urllib.parse import quote
            encoded = quote(str(value), safe='')
        except Exception:
            encoded = str(value)
        return encoded

    # Perform the substitution
    return re.sub(pattern, _sub, url)

def is_none_string(val: any) -> bool:
    """Check if a string represents a None value."""
    if isinstance(val, str):
        stripped = val.strip()
        if not stripped:
            return True
        if stripped.lower() == "none":
            return True
    return False

def parser_flags(parser):
    '''
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    '''
    if parser is None:
        return ''

    # argparse stores all option strings in a dict mapping each flag to its action.
    # This preserves the order in which flags were added.
    try:
        flag_list = list(parser._option_string_actions.keys())
    except AttributeError:
        # Fallback: iterate over the actions if the internal dict is not available.
        flag_list = []
        seen = set()
        for action in getattr(parser, '_actions', []):
            for opt in action.option_strings:
                if opt and opt not in seen:
                    flag_list.append(opt)
                    seen.add(opt)

    return ' '.join(flag_list)

def int_to_string(number: int, alphabet: list, padding=None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    # Basic validation of the alphabet
    if not isinstance(alphabet, list):
        raise TypeError("alphabet must be a list of single-character strings.")
    if len(alphabet) < 2:
        raise ValueError("alphabet must contain at least two unique characters.")
    if len(set(alphabet)) != len(alphabet):
        raise ValueError("alphabet must contain unique characters.")
    if any(not isinstance(c, str) or len(c) != 1 for c in alphabet):
        raise ValueError("each element of alphabet must be a single-character string.")

    base = len(alphabet)

    # Validate padding
    if padding is not None:
        if not isinstance(padding, int):
            raise TypeError("padding must be an integer or None.")
        if padding < 0:
            raise ValueError("padding must be non-negative.")

    # Handle negative numbers: prepend '-' and convert the absolute value
    if number < 0:
        sign = '-'
        number = -number
    else:
        sign = ''

    # Special case for zero
    if number == 0:
        result = alphabet[0]
        if padding is not None:
            # Pad with leading zeros (alphabet[0])
            result = alphabet[0] * padding
        return sign + result

    # Convert number to string in the given base
    digits = []
    n = number
    while n > 0:
        digits.append(alphabet[n % base])
        n //= base
    digits.reverse()

    result = ''.join(digits)

    if padding is not None and len(result) < padding:
        result = alphabet[0] * (padding - len(result)) + result

    return sign + result

def replace_dots(value, arg):
    """
    Replaces all occurrences of '.' in the given string with the specified arg.

    Args:
        value (str): The original string.
        arg (str): The replacement string.

    Returns:
        str: The string with all '.' replaced by arg.

    Raises:
        ValueError: If value or arg are None or not convertible to string.
    """
    if value is None:
        raise ValueError("value must not be None")
    if arg is None:
        raise ValueError("arg must not be None")
    try:
        value_str = str(value)
    except Exception as exc:
        raise ValueError(f"Cannot convert value to string: {exc}") from exc
    try:
        arg_str = str(arg)
    except Exception as exc:
        raise ValueError(f"Cannot convert arg to string: {exc}") from exc
    return value_str.replace('.', arg_str)

def subclasses(cls):
    """Return all subclasses of a class, recursively"""
    if not isinstance(cls, type):
        raise TypeError("The argument must be a class")
    seen = set()
    stack = [cls]
    while stack:
        current = stack.pop()
        for subcls in current.__subclasses__():
            if subcls not in seen:
                seen.add(subcls)
                stack.append(subcls)
    return seen

import os
def os_is_mac():
    """
    Checks if the OS is macOS

    :return: True if macOS
    :rtype: bool
    """
    try:
        import sys
        return sys.platform.startswith('darwin')
    except Exception:
        return False

def unquote(name):
    """Remove quote from the given name."""
    if not isinstance(name, str):
        raise TypeError("name must be a string")
    if len(name) > 1 and name[0] == name[-1] and name[0] in ('"', "'"):
        inner = name[1:-1]
        q = name[0]
        if q == '"':
            return inner.replace(r'\"', '"')
        return inner.replace(r"\'", "'")
    return name

import re, sys, shlex

def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    Parameters
    ----------
    s : str or bytes
        Input command line.
    platform : str or int, optional
        'this' = auto from current platform;
        1 = POSIX;
        0 = Windows/CMD
        (other values reserved)

    Returns
    -------
    list[str]
        List of arguments.
    """
    # Ensure string
    if isinstance(s, bytes):
        try:
            s = s.decode(sys.getdefaultencoding())
        except Exception:
            s = s.decode(errors='replace')
    if not isinstance(s, str):
        raise TypeError(f"Input must be str or bytes, got {type(s).__name__}")

    if s == '':
        return []

    # Resolve platform
    if platform == 'this':
        platform = 0 if sys.platform.startswith('win') else 1
    elif isinstance(platform, str):
        # allow '1' '0'
        if platform.isdigit():
            platform = int(platform)
    elif not isinstance(platform, int):
        raise TypeError(f"Platform must be int or 'this', got {type(platform).__name__}")

    # POSIX: delegate to shlex (fast enough for most cases)
    if platform == 1:
        try:
            return shlex.split(s, posix=True)
        except Exception as e:
            raise ValueError(f"Failed to split POSIX command: {e}") from e

    # Windows/CMD: simple regex-based split (does not fully emulate cmd.exe rules)
    if platform == 0:
        # Pattern: capture quoted segments or non-whitespace segments
        pattern = r'''(?:"([^"]*)"|([^\s"]+))'''
        args = []
        for match in re.finditer(pattern, s):
            quoted, unquoted = match.groups()
            if quoted is not None:
                args.append(quoted)
            elif unquoted is not None:
                args.append(unquoted)
        # Handle isolated quotes or unclosed quote: fallback split on whitespace
        if not args and re.search(r'"|\'', s):
            # naive fallback: remove surrounding quotes
            tokens = shlex.split(s, posix=False)
            return tokens
        return args

    # Reserved / unknown platform
    raise ValueError(f"Unsupported platform indicator: {platform}")

def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    if not host:
        return False

    try:
        # Try interpreting host as an IP address first
        import ipaddress
        ip = ipaddress.ip_address(host)
        return ip.is_loopback
    except ValueError:
        # Not a literal IP – attempt to resolve it
        try:
            addrinfo = socket.getaddrinfo(host, None)
        except socket.gaierror:
            return False

        for family, _, _, _, sockaddr in addrinfo:
            # sockaddr[0] contains the IP string
            ip_candidate = sockaddr[0]
            try:
                ip = ipaddress.ip_address(ip_candidate)
            except ValueError:
                continue
            if ip.is_loopback:
                return True

        return False

def write_configuration(config_filename, rendered_config, mode=0o600, overwrite=False):
    '''
    Given a target config filename and rendered config YAML, write it out to file.
    Create any containing directories as needed. But if the file already exists and
    overwrite is False, abort before writing anything.
    '''
    if not isinstance(config_filename, str):
        raise ValueError('config_filename must be a string representing a file path')
    # Expand user and normalize path
    config_path = os.path.expanduser(config_filename)
    # If file exists and we are not allowed to overwrite, do nothing
    if os.path.isfile(config_path) and not overwrite:
        return
    # Ensure the containing directory exists
    directory = os.path.dirname(config_path)
    if directory and not os.path.isdir(directory):
        try:
            os.makedirs(directory, exist_ok=True)
        except OSError as e:
            # If the directory cannot be created and does not already exist, re-raise
            if not os.path.isdir(directory):
                raise
    # Prepare YAML content to write
    if isinstance(rendered_config, str):
        content = rendered_config
    else:
        try:
            import yaml
        except ImportError as e:
            raise ImportError('yaml module is required to dump configuration content') from e
        content = yaml.dump(rendered_config, default_flow_style=False, width=float('inf'))
    # Write to file
    try:
        with open(config_path, 'w', encoding='utf-8') as f:
            f.write(content)
    except OSError as e:
        raise OSError(f'Failed to write configuration to {config_path}') from e
    # Set file permissions
    try:
        os.chmod(config_path, mode)
    except OSError as e:
        # If permissions can't be set, ignore silently or log
        pass
    return config_path

def _resolve_string(matcher):
    """
    Get the value from environment given a matcher containing a name and an optional default value.
    If the variable is not defined in environment and no default value is provided, an Error is raised.
    """
    # Extract variable name from matcher
    try:
        # If matcher is a regex match object
        name = matcher.group('name')
    except AttributeError:
        # If matcher behaves like a dict
        try:
            name = matcher['name']
        except Exception as e:
            raise TypeError("Matcher must provide a 'name' field or group") from e

    # Extract default if present
    default = None
    try:
        # Regex match groups may return None if not matched
        default = matcher.group('default')
    except AttributeError:
        try:
            default = matcher.get('default', None)
        except Exception:
            # No default; keep None
            pass

    # Retrieve from environment
    value = os.getenv(name, default)

    if value is None and default is None:
        raise EnvironmentError(f"Environment variable {name!r} not found and no default provided")

    return value

def _parse_image_ref(image_href: str) -> Tuple[str, str, bool]:
    """Parse an image href into composite parts.

    :param image_href: href of an image
    :returns: a tuple of the form (image_id, netloc, use_ssl)
    :raises ValueError:
    """
    if not isinstance(image_href, str):
        raise ValueError(f"image_href must be a string, got {type(image_href)}")

    try:
        parsed = urllib.parse.urlparse(image_href)
    except Exception as exc:
        raise ValueError(f"Failed to parse URL '{image_href}': {exc}") from exc

    if parsed.scheme not in {'http', 'https'}:
        raise ValueError(f"Unsupported URL scheme '{parsed.scheme}' in '{image_href}'")

    netloc = parsed.netloc
    use_ssl = parsed.scheme == 'https'

    # Extract the image id from the path, stripping trailing slashes and extensions
    path = parsed.path.rstrip('/')
    if not path:
        raise ValueError(f"No path component found in URL '{image_href}'")

    # The image ID is expected to be the last part of the path
    image_id_part = path.split('/')[-1]
    if not image_id_part:
        raise ValueError(f"Empty image identifier in URL '{image_href}'")

    # Remove any file extension (e.g. '.jpg', '.png'), if present
    if '.' in image_id_part:
        image_id = image_id_part.split('.')[0]
    else:
        image_id = image_id_part

    if not image_id:
        raise ValueError(f"Unable to extract image ID from '{image_href}'")

    return image_id, netloc, use_ssl

def get_pattern(pattern, strip=True):
    """This method converts the given string to regex pattern"""
    if pattern is None:
        raise ValueError("Pattern cannot be None")
    # If pattern is already a compiled regex, return it unchanged.
    regex_type = getattr(re, "Pattern", None) or getattr(re, "_pattern_type", None)
    if regex_type and isinstance(pattern, regex_type):
        return pattern
    if not isinstance(pattern, str):
        raise TypeError(f"Pattern must be a string or compiled regex object, got {type(pattern).__name__}")
    if strip:
        pattern = pattern.strip()
    try:
        return re.compile(pattern)
    except re.error as exc:
        raise ValueError(f"Invalid regex pattern: {exc}") from exc

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    # Build the command list
    if isinstance(commands, str):
        cmd_list = [commands]
    else:
        try:
            cmd_list = list(commands)
        except Exception as exc:
            raise TypeError("commands must be a string or a sequence") from exc

    if args is not None:
        if isinstance(args, str):
            args_list = [args]
        else:
            try:
                args_list = list(args)
            except Exception as exc:
                raise TypeError("args must be a string or a sequence") from exc
        cmd_list.extend(args_list)

    if not cmd_list:
        raise ValueError("No command specified")

    # Execute and capture output
    stderr_option = subprocess.DEVNULL if hide_stderr else subprocess.PIPE
    if verbose:
        try:
            # Use shlex to avoid unsafe printing for arguments containing spaces
            import shlex
            printable = shlex.join(cmd_list)
        except AttributeError:
            # shlex.join not available pre-Python 3.8
            printable = " ".join(cmd_list)
        print(f"Running command: {printable}")

    try:
        result = subprocess.run(
            cmd_list,
            cwd=cwd,
            stdout=subprocess.PIPE,
            stderr=stderr_option,
            env=env,
            text=True,
            check=False,
        )
        if result.returncode != 0:
            # Include stdout and stderr in the error for debugging
            raise subprocess.CalledProcessError(
                result.returncode,
                cmd_list,
                output=result.stdout,
                stderr=result.stderr,
            )
        return result.stdout
    except Exception as exc:
        # Re-raise to preserve stack trace, but wrap Beney our errors nicely
        raise RuntimeError(f"Failed to run command {cmd_list!r}") from exc

def is_ipv4(target):
    """ Test if IPv4 address or not """
    if isinstance(target, ipaddress.IPv4Address):
        return True
    try:
        return isinstance(ipaddress.ip_address(target), ipaddress.IPv4Address)
    except (ValueError, TypeError):
        return False

def _dump_string(obj, dumper=None):
    """Dump to a py2-unicode or py3-string"""
    import sys
    if dumper is None:
        yaml_str = yaml.safe_dump(obj, allow_unicode=True)
    else:
        yaml_str = yaml.dump(obj, Dumper=dumper, allow_unicode=True)
    if sys.version_info[0] == 2:
        return yaml_str.decode('utf8')
    return yaml_str

def make_array(shape, dtype=np.dtype("float32")):
    """
    Function to create an array with shape and dtype.

    Parameters
    ----------
    shape : tuple
        shape of the array to create
    dtype : `numpy.dtype`
        data-type of the array to create
    """
    # Ensure dtype is a numpy dtype
    try:
        dtype = np.dtype(dtype)
    except Exception as exc:
        raise TypeError(f"Invalid dtype {dtype!r}") from exc

    # Normalize the shape to a tuple
    if isinstance(shape, int):
        shape = (shape,)
    elif isinstance(shape, (list, tuple)):
        shape = tuple(shape)
    else:
        raise TypeError(
            f"Shape must be an int or a tuple/list of ints, got {type(shape).__name__}"
        )

    # Validate that all dimensions are non‑negative integers
    if any(not isinstance(dim, int) or dim < 0 for dim in shape):
        raise ValueError(f"All shape dimensions must be non‑negative integers, got {shape}")

    try:
        arr = np.empty(shape, dtype=dtype)
    except Exception as exc:
        raise ValueError(
            f"Could not allocate array with shape {shape} and dtype {dtype}"
        ) from exc

    return arr

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file.
    Return the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    import os
    import logging
    import json

    results = {}
    error_records = []

    # Use a local logger to create LogRecord objects
    _logger = logging.getLogger('config_loader')

    # Helper to create a LogRecord for an error
    def _make_error(filename, message):
        return _logger.makeRecord(
            name=_logger.name,
            level=logging.ERROR,
            fn=filename,
            lno=0,
            msg=message,
            args=(),
            exc_info=None,
            extra={}
        )

    # Helper to resolve environment variables in strings recursively
    def _resolve_env_in_value(value):
        import re
        if isinstance(value, str):
            # Replace ${VAR} with environment variable
            pattern = re.compile(r'\$\{([^}]+)\}')
            def repl(match):
                return os.getenv(match.group(1), '')
            return pattern.sub(repl, value)
        elif isinstance(value, dict):
            return {k: _resolve_env_in_value(v) for k, v in value.items()}
        elif isinstance(value, list):
            return [_resolve_env_in_value(v) for v in value]
        else:
            return value

    for fname in config_filenames:
        if not os.path.isfile(fname):
            error_records.append(_make_error(fname, f"Configuration file not found: {fname}"))
            continue
        try:
            with open(fname, 'r', encoding='utf-8') as f:
                raw = f.read()
            # Determine parser by file extension
            _, ext = os.path.splitext(fname.lower())
            if ext in {'.yaml', '.yml'}:
                try:
                    import yaml
                except Exception as e:
                    error_records.append(_make_error(fname, f"YAML parser not available: {e}"))
                    continue
                cfg = yaml.safe_load(raw)
            elif ext == '.toml':
                try:
                    import toml
                except Exception as e:
                    error_records.append(_make_error(fname, f"TOML parser not available: {e}"))
                    continue
                cfg = toml.loads(raw)
            elif ext == '.json':
                try:
                    cfg = json.loads(raw)
                except json.JSONDecodeError as e:
                    error_records.append(_make_error(fname, f"JSON decode error: {e}"))
                    continue
            else:
                # Default to JSON for unknown extensions
                try:
                    cfg = json.loads(raw)
                except json.JSONDecodeError:
                    error_records.append(_make_error(fname, f"Unrecognized file type and failed JSON parsing for {fname}"))
                    continue

            if not isinstance(cfg, dict):
                error_records.append(_make_error(fname, f"Configuration is not a dictionary: got {type(cfg).__name__}"))
                continue

            if resolve_env:
                cfg = _resolve_env_in_value(cfg)

            if overrides and isinstance(overrides, dict):
                # Simple overlay of overrides onto cfg
                cfg.update(overrides)

            results[fname] = cfg
        except Exception as exc:
            error_records.append(_make_error(fname, f"Unexpected error during loading: {exc}"))
    return results, error_records

def force_string(obj):
    """
    This function returns the bytes object corresponding to ``obj`` in case
    it is a string using UTF-8.
    """
    if isinstance(obj, str):
        try:
            return obj.encode('utf-8')
        except Exception as exc:
            raise ValueError(f"Error encoding string to bytes: {exc}") from exc
    return obj

def protocol_handlers(cls, protocol_version=None):
        """ Return a dictionary of available Bolt protocol handlers,
        keyed by version tuple. If an explicit protocol version is
        provided, the dictionary will contain either zero or one items,
        depending on whether that version is supported. If no protocol
        version is provided, all available versions will be returned.

        :param protocol_version: tuple identifying a specific protocol
            version (e.g. (3, 5)) or None
        :return: dictionary of version tuple to handler class for all
            relevant and supported protocol versions
        :raise TypeError: if protocol version is not passed in a tuple
        """
        handlers = {}
        # Inspect class attributes for nested handler classes
        for name, obj in vars(cls).items():
            if isinstance(obj, type):
                # Look for a special attribute indicating protocol version
                version = getattr(obj, "_protocol_version", None)
                if (
                    isinstance(version, tuple)
                    and len(version) == 2
                    and all(isinstance(v, int) for v in version)
                ):
                    handlers[version] = obj

        if protocol_version is not None:
            if not isinstance(protocol_version, tuple):
                raise TypeError("protocol_version must be a tuple of two integers")
            # Return only the handler for the requested version if present
            return {protocol_version: handlers[protocol_version]} if protocol_version in handlers else {}
        return handlers

@classmethod
    def from_raw_values(cls, values):
        """Create a Bookmarks object from a list of raw bookmark string values.

        You should not need to use this method unless you want to deserialize
        bookmarks.

        :param values: ASCII string values (raw bookmarks)
        :type values: Iterable[str]
        """
        # Validate that we received an iterable of strings
        try:
            iterator = iter(values)
        except TypeError:
            raise TypeError("Provided values must be an iterable of strings")

        # Create an empty Bookmarks instance
        bookmarks = cls()

        for raw in iterator:
            if not isinstance(raw, str):
                raise TypeError(f"Invalid bookmark value {raw!r}: must be a string")

            # Prefer a dedicated raw-value constructor if available, otherwise
            # fall back to the generic Bookmark constructor.
            try:
                # Assume a Bookmark class exists in the same module
                bookmark = Bookmark(raw)
            except NameError:
                # If Bookmark is not defined, simply store the raw string
                bookmark = raw
            except Exception as exc:
                raise ValueError(f"Failed to create Bookmark from raw value {raw!r}") from exc

            bookmarks.append(bookmark)

        return bookmarks

def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type).
    """
    # Determine type name of the original object
    seq_type = type(seq).__name__
    if seq is None:
        return (None, seq_type)
    # If seq is a string or bytes, return it directly
    if isinstance(seq, (str, bytes)):
        return (seq, seq_type)
    # If seq is an iterable (but not a string/bytes), materialize it
    if hasattr(seq, "__iter__") and not isinstance(seq, (str, bytes)):
        try:
            if bufsize is not None:
                seq_list = []
                for i, item in enumerate(seq):
                    if i >= bufsize:
                        break
                    seq_list.append(item)
            else:
                seq_list = list(seq)
            return (seq_list, seq_type)
        except TypeError:
            # Fall back if conversion fails
            pass
    # Fallback: treat the input as a single scalar element
    return ([seq], seq_type)

def hist_to_graph(hist, make_value=None, get_coordinate="left",
                  field_names=("x", "y"), scale=None):
    """
    Convert a :class:`.histogram` to a :class:`.graph`.

    *make_value* is a function to set the value of a graph's point.
    By default it is bin content.
    *make_value* accepts a single value (bin content) without context.

    This option could be used to create graph's error bars.
    For example, to create a graph with errors
    from a histogram where bins contain
    a named tuple with fields *mean*, *mean_error* and a context
    one could use

    >>> make_value = lambda bin_: (bin_.mean, bin_.mean_error)

    *get_coordinate* defines what the coordinate
    of a graph point created from a histogram bin will be.
    It can be "left" (default), "right" and "middle".

    *field_names* set field names of the graph. Their number
    must be the same as the dimension of the result.
    For a *make_value* above they would be
    *("x", "y_mean", "y_mean_error")*.

    *scale* becomes the graph's scale (unknown by default).
    If it is ``True``, it uses the histogram scale.

    *hist* must contain only numeric bins (without context)
    or *make_value* must remove context when creating a numeric graph.

    Return the resulting graph.
    """
    # Helper class to wrap graph data
    class _SimpleGraph:
        def __init__(self, data):
            self._data = data

        def __getitem__(self, key):
            return self._data[key]

        def __repr__(self):
            return f"<SimpleGraph fields={list(self._data.keys())}>"

    # ---- Validate input ----
    # Histogram should expose edges and values (or content)
    try:
        edges = getattr(hist, "edges")
    except AttributeError:
        raise TypeError("histogram object must have an 'edges' attribute")

    try:
        values = getattr(hist, "values")
    except AttributeError:
        try:
            values = getattr(hist, "content")
        except AttributeError:
            raise TypeError("histogram object must have a 'values' or 'content' attribute")

    if not isinstance(edges, (list, tuple)):
        raise TypeError("'edges' attribute must be a list or tuple of bin boundaries")
    if not isinstance(values, (list, tuple)):
        raise TypeError("'values' attribute must be a list or tuple of bin contents")

    n_bins = len(values)
    if len(edges) != n_bins + 1:
        raise ValueError("Number of edges must be one more than number of values")

    # ---- Build coordinates ----
    coords = []
    for i in range(n_bins):
        left = float(edges[i])
        right = float(edges[i + 1])
        if get_coordinate == "left":
            coord = left
        elif get_coordinate == "right":
            coord = right
        elif get_coordinate == "middle":
            coord = (left + right) / 2.0
        else:
            raise ValueError("get_coordinate must be 'left', 'right' or 'middle'")
        coords.append(coord)

    # ---- Apply make_value ----
    if make_value is None:
        # Default: bin content is the value
        result_values = values
    else:
        # make_value could return a tuple or a scalar
        result_values = []
        for v in values:
            try:
                rv = make_value(v)
            except Exception as err:
                raise ValueError(f"make_value raised an exception for bin value {v!r}: {err}") from err
            result_values.append(rv)

    # ---- Assemble graph data ----
    graph_data = {}
    if len(field_names) == 0:
        raise ValueError("field_names must have at least one entry")

    # First field is always the coordinate
    graph_data[field_names[0]] = coords

    # Interpret result_values
    if isinstance(result_values[0], (tuple, list)):
        # Multiple output values per bin
        n_out = len(result_values[0])
        if len(field_names) - 1 != n_out:
            raise ValueError(
                "Number of outputs from make_value does not match "
                f"number of non‑coordinate field_names ({len(field_names)-1})"
            )
        for idx, name in enumerate(field_names[1:]):
            graph_data[name] = [rv[idx] for rv in result_values]
    else:
        # Single output value per bin
        if len(field_names) != 2:
            raise ValueError(
                "For single output value from make_value, field_names must have two entries"
            )
        graph_data[field_names[1]] = result_values

    # ---- Return graph ----
    return _SimpleGraph(graph_data)

def verifyObject(iface, candidate, tentative=False):
    """
    Verify that *candidate* might correctly provide *iface*.

    This involves:

    - Making sure the candidate claims that it provides the
    interface using ``iface.providedBy`` (unless *tentative* is `True`,
    in which case this step is skipped). This means that the candidate's class
    declares that it `implements <zope.interface.implementer>` the interface,
    or the candidate itself declares that it `provides <zope.interface.provider>`
    the interface

    - Making sure the candidate defines all the necessary methods

    - Making sure the methods have the correct signature (to the
    extent possible)

    - Making sure the candidate defines all the necessary attributes

    :return bool: Returns a true value if everything that could be
    checked passed.
    :raises zope.interface.Invalid: If any of the previous
    conditions does not hold.

    .. versionchanged:: 5.0
        If multiple methods or attributes are invalid, all such errors
        are collected and reported. Previously, only the first error was reported.
        As a special case, if only one such error is present, it is raised
        alone, like before.
    """
    try:
        import inspect
    except Exception as exc:
        raise ValueError("inspect module not available") from exc

    from zope.interface import Invalid

    errors = []

    # Check that candidate claims to provide the interface if not tentative
    if not tentative:
        try:
            if not iface.providedBy(candidate):
                errors.append(f"Candidate {candidate!r} does not claim to provide {iface!r}")
        except Exception:
            errors.append(f"Unable to evaluate providedBy for {candidate!r}")

    # Helper to compare signatures
    def signatures_match(sig1, sig2):
        params1 = list(sig1.parameters.values())
        params2 = list(sig2.parameters.values())
        if len(params1) != len(params2):
            return False
        for p1, p2 in zip(params1, params2):
            if p1.kind != p2.kind or p1.name != p2.name:
                return False
            # If interface has default value, candidate must provide same default
            if p1.default is not inspect.Parameter.empty and p1.default != p2.default:
                return False
            # If interface has no default, candidate must also have no default
            if p1.default is inspect.Parameter.empty and p2.default is not inspect.Parameter.empty:
                return False
        return True

    # Iterate over interface names
    for name in iface:
        # Skip deprecated special names that don't require presence
        if name.startswith('_'):
            continue
        iface_value = getattr(iface, name, None)
        if iface_value is None:
            continue
        try:
            cand_value = getattr(candidate, name, None)
        except Exception:
            cand_value = None
        if cand_value is None:
            errors.append(f"Candidate missing required attribute/method '{name}'")
            continue

        # If interface defines a method, check for callability and signature
        is_method = False
        # Interface methods are typically zope.interface._api.Method instances
        # or plain callables; we treat any callable on interface as method.
        try:
            iface_sig = iface_value.__signature__
        except AttributeError:
            iface_sig = None
        if iface_sig is None and callable(iface_value):
            try:
                iface_sig = inspect.signature(iface_value)
            except Exception:
                iface_sig = None
        if iface_sig is not None:
            is_method = True

        if is_method:
            if not callable(cand_value):
                errors.append(f"Attribute '{name}' should be callable")
                continue
            try:
                cand_sig = inspect.signature(cand_value)
            except Exception:
                cand_sig = None
            if cand_sig is None:
                errors.append(f"Could not determine signature of candidate method '{name}'")
            else:
                if not signatures_match(iface_sig, cand_sig):
                    errors.append(
                        f"Signature mismatch for method '{name}': "
                        f"expected {iface_sig}, got {cand_sig}"
                    )
        # For attributes, no signature check - only presence is checked above

    if errors:
        if len(errors) == 1:
            raise Invalid(errors[0])
        else:
            raise Invalid("Multiple interface validation errors: " + "; ".join(errors))
    return True

def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.

    The function checks whether *candidate* is a subclass of *iface* if both are
    type objects.  If that is not the case, the function compares the public
    attribute names of *iface* with those of *candidate* (or its class) and
    ensures that the candidate implements all required attributes.  The
    *tentative* flag turns the verification into a non‑exceptional check:
    when ``tentative=True`` the function simply returns ``False`` if the check
    fails instead of raising an ``AttributeError``.
    """
    if iface is None or candidate is None:
        raise ValueError('iface and candidate must not be None')
    # Resolve the class of the candidate
    target_cls = candidate if isinstance(candidate, type) else candidate.__class__
    # First, try a straightforward subclass test
    try:
        if issubclass(target_cls, iface):
            return True
    except TypeError:
        # Either iface or target_cls is not a class – fall back to attribute check
        pass
    # Gather the public members of the interface
    required_attrs = [
        name
        for name in dir(iface)
        if not name.startswith("_")
        and name not in {"__doc__", "__module__", "__dict__", "__weakref__"}
    ]
    missing = [name for name in required_attrs if not hasattr(target_cls, name)]
    if missing:
        if tentative:
            return False
        raise AttributeError(
            f"Candidate {candidate!r} does not provide required attributes "
            f"for iface {iface!r}: {missing}"
        )
    # If the interface defines callables, ensure they are also callables
    for name in required_attrs:
        interface_member = getattr(iface, name)
        candidate_member = getattr(target_cls, name)
        if callable(interface_member) and not callable(candidate_member):
            if tentative:
                return False
            raise TypeError(
                f"Candidate {candidate!r} attribute '{name}' must be callable "
                f"to satisfy iface {iface!r}"
            )
    return True

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__."""
    # Validate explicit metaclass
    if explicit_mc is not None:
        if not isinstance(explicit_mc, type):
            raise TypeError(f"explicit __metaclass__ {explicit_mc!r} is not a type")
    # If no bases and no explicit metaclass, default to type
    if not bases:
        return explicit_mc or type
    # Validate base classes and collect their metaclasses
    base_metas = []
    for base in bases:
        if not isinstance(base, type):
            raise TypeError(f"base {base!r} is not a type")
        base_metas.append(base.__class__)
    # Build candidate list: explicit then base metas
    candidates = []
    if explicit_mc:
        candidates.append(explicit_mc)
    candidates.extend(base_metas)
    # Remove duplicates while preserving order
    seen = set()
    metas = []
    for m in candidates:
        if m not in seen:
            seen.add(m)
            metas.append(m)
    # Determine the most derived compatible metaclass
    for mc in metas:
        if all(issubclass(mc, other) or mc is other for other in metas):
            return mc
    # No compatible metaclass found
    raise TypeError(f"metaclass conflict: {', '.join(m.__name__ for m in metas)} during class creation")

def pop(self, key, default=__marker):
    """
    D.pop(k[,d]) -> v, remove specified key and return the corresponding value.
    If key is not found, d is returned if given, otherwise KeyError is raised.
    """
    # Check for key existence first to decide whether to raise or return default
    try:
        if default is __marker:
            value = self[key]
            del self[key]
            return value
        else:
            if key in self:
                value = self[key]
                del self[key]
                return value
            else:
                return default
    except KeyError:
        # Propagate KeyError if default not provided
        if default is __marker:
            raise
        # If custom default is provided, return it
        return default
    except Exception:
        # For any other exception (e.g., unhashable key), propagate it
        raise

def popitem(self):
    """Remove and return the `(key, value)` pair least frequently used."""
    # If the container is empty raise KeyError
    if len(self) == 0:
        raise KeyError('popitem(): dictionary is empty')
    # Attempt to retrieve a frequency map if present
    freq_map = getattr(self, "_freq", None)
    # Choose the key with smallest frequency if possible
    if isinstance(freq_map, dict) and freq_map:
        try:
            key = min(freq_map, key=freq_map.get)
        except Exception:
            key = next(iter(self))
    else:
        key = next(iter(self))
    # Remove the item from the dictionary
    value = self.pop(key)
    # Clean up frequency information if it exists
    if isinstance(freq_map, dict):
        freq_map.pop(key, None)
    return (key, value)

def popitem(self):
    """Remove and return the `(key, value)` pair least recently used."""
    try:
        # `popitem(last=False)` on an OrderedDict removes the first item,
        # which we treat as the least recently used.
        return self._data.popitem(last=False)
    except AttributeError:
        # If the underlying storage isn't an OrderedDict we can't guarantee
        # LRU order; re-raise a clear error to surface the issue.
        raise AttributeError(
            "Underlying storage `_data` must be an OrderedDict "
            "to support LRU popitem."
        )
    except KeyError:
        # Re-raise the KeyError to indicate the structure is empty.
        raise KeyError("popitem from an empty structure")

def popitem(self):
    """Remove and return a random `(key, value)` pair."""
    import random
    # Ensure dictionary is not empty
    if len(self) == 0:
        raise KeyError('dict is empty')
    try:
        # Randomly select a key from the current keys
        key = random.choice(list(self.keys()))
        # Pop the key-value pair
        value = self.pop(key)
        return (key, value)
    except Exception as e:
        # Re-raise as KeyError if something unexpected happened during pop
        raise KeyError(str(e)) from e

def _create_in_regex(self) -> Pattern:
    """
    Create the in-style parameter regular expression.

    Returns the in-style parameter regular expression (:class:`re.Pattern`).
    """
    # Obtain the list of values for the 'in' operator. Try a few common attribute names.
    values = None
    for attr in ("_in", "_in_values", "in_values", "in"):
        if hasattr(self, attr):
            values = getattr(self, attr)
            break

    # If no values or empty, return a pattern that matches nothing.
    if not values:
        return re.compile('(?!)')

    # Ensure all values are strings and escape regex metacharacters.
    try:
        escaped_values = [re.escape(str(v)) for v in values]
    except Exception as exc:
        # If any error occurs, fall back to a non-matching pattern.
        return re.compile('(?!)')

    # Build a regex that matches any one of the values, anchored.
    pattern_str = r'^(?:' + '|'.join(escaped_values) + r')$'

    try:
        return re.compile(pattern_str)
    except re.error:
        # If the compiled pattern fails, return a non-matching pattern.
        return re.compile('(?!)')

def _create_converter(self) -> _converting._Converter:
    """Create the parameter style converter.

    Returns the parameter style converter (:class:`._converting._Converter`).
    """
    try:
        return _converting._Converter()
    except Exception as exc:
        raise RuntimeError("Failed to create converter") from exc

def default_tzinfo(dt, tzinfo):
    """Sets the ``tzinfo`` parameter on naive datetimes only

    This is useful for example when you are provided a datetime that may have
    either an implicit or explicit time zone, such as when parsing a time zone
    string.
    """
    # dt must be a datetime-like object with a tzinfo attribute
    if dt is None:
        return None
    if not hasattr(dt, "tzinfo"):
        raise TypeError("dt must be a datetime instance with a tzinfo attribute")
    # If dt is naive, apply the provided tzinfo
    if dt.tzinfo is None:
        try:
            return dt.replace(tzinfo=tzinfo)
        except Exception:
            # In case replace is not available (e.g., unexpected type), return original.
            return dt
    # dt is already timezone aware; leave unchanged
    return dt

def identify_request(request: RequestType):
    """Try to identify whether this is a Diaspora request.

    Try first public message. Then private message. The check if this is a legacy payload.
    """
    # Ensure required attributes exist
    body = getattr(request, "body", None)
    if body is None:
        return False

    # Normalise body to string
    if isinstance(body, bytes):
        try:
            body = body.decode("utf-8")
        except Exception:
            try:
                body = body.decode("latin-1")
            except Exception:
                body = ""

    # Attempt to parse as JSON
    try:
        import json
        data = json.loads(body)
        if isinstance(data, dict) and "encrypted_magic_envelope" in data:
            return True
    except Exception:
        pass

    # Attempt to parse as XML
    try:
        import xml.etree.ElementTree as ET
        root = ET.fromstring(body)
        # The tag used for a public Diaspora message (legacy)
        if root.tag == "magicEnvelope":
            return True
    except Exception:
        pass

    return False

def identify_request(request: RequestType) -> bool:
    """
    Try to identify whether this is a Matrix request
    """
    # Basic guard for empty or None request
    if not request:
        return False

    # Matrix requests are typically routed under the `/_matrix` URI scheme.
    # Use the standard `path` or `path_info` attributes which are present on
    # most request objects in popular web frameworks (WSGI, Django, Flask, …).
    try:
        path = getattr(request, "path", None)
        if path is None:
            # Some frameworks expose `path_info` instead of `path`.
            path = getattr(request, "path_info", None)
    except Exception:
        path = None

    if path and isinstance(path, str) and path.startswith("/_matrix"):
        return True

    # Fall back to checking HTTP headers for the Matrix client User‑Agent.
    # Header keys may be provided via a `headers` dict, a `META` dict, or via
    # attribute access. Normalize the key lookup case‑insensitively.
    header_user_agent = None
    try:
        # Common header maps
        if hasattr(request, "headers") and isinstance(request.headers, dict):
            header_user_agent = request.headers.get("User-Agent") or request.headers.get("user-agent")
        elif hasattr(request, "META") and isinstance(request.META, dict):
            header_user_agent = request.META.get("HTTP_USER_AGENT")
    except Exception:
        header_user_agent = None

    if header_user_agent and isinstance(header_user_agent, str):
        if "matrix" in header_user_agent.lower():
            return True

    # If nothing matched, we cannot confidently say it is a Matrix request.
    return False

def find_tags(text: str, replacer: callable = None) -> Tuple[Set, str]:
    """Find tags in text.

    Tries to ignore tags inside code blocks.

    Optionally, if passed a "replacer", will also replace the tag word with the result
    of the replacer function called with the tag word.

    Returns a set of tags and the original or replaced text.
    """
    # Regex to find tags of form "# <TAG>" or "# TAG:" or "# TAG"
    tag_pattern = re.compile(r'#\s*(?:<(?P<tag1>\w+)>|(?P<tag2>\w+)\s*:?)')

    tags: Set[str] = set()
    in_code: bool = False
    # Preserve line endings
    lines = text.splitlines(True)
    new_lines: List[str] = []

    for line in lines:
        # Toggle code block state when encountering a line that starts an entry
        if line.lstrip().startswith('```'):
            in_code = not in_code
            new_lines.append(line)
            continue

        # If we are not inside a code block, find tags
        if not in_code:
            for m in tag_pattern.finditer(line):
                tag = m.group('tag1') or m.group('tag2')
                if tag:
                    tags.add(tag)

        # If a replacer is provided, replace tags accordingly
        if replacer is not None:
            def repl_func(match):
                tag = match.group('tag1') or match.group('tag2')
                if tag is None:
                    return match.group(0)
                try:
                    new_tag = str(replacer(tag))
                except Exception:
                    new_tag = tag
                return '# ' + new_tag

            line = tag_pattern.sub(repl_func, line)

        new_lines.append(line)

    return tags, ''.join(new_lines)

def process_text_links(text):
    """Process links in text, adding some attributes and linkifying textual links."""
    try:
        # Ensure input is a string
        if not isinstance(text, str):
            text = str(text)

        # Regular expression to find URLs (http://, https://, or www.)
        url_pattern = re.compile(r'\b((?:https?://|www\.)[^\s<]+?)\b')

        def replace_match(m):
            url = m.group(1)
            # Ensure URLs starting with 'www.' have a scheme
            if url.startswith('www.'):
                href = 'http://' + url
            else:
                href = url
            # Attributes to add to every link
            attrs = 'target="_blank" rel="noopener noreferrer"'
            return f'<a href="{href}" {attrs}>{url}</a>'

        return url_pattern.sub(replace_match, text)
    except Exception:
        # In case of any unexpected error, return the original text
        return text

def test_tag(tag: str) -> bool:
    """Test a word whether it could be accepted as a tag."""
    if not isinstance(tag, str):
        raise TypeError("'tag' must be a string")
    if not tag:
        return False
    if len(tag) > 20:
        return False
    if tag[0].isdigit():
        return False
    for ch in tag:
        if not (ch.isalnum() or ch == "_"):
            return False
    return True

def xml_children_as_dict(node):
    """Turn the children of node <xml> into a dict, keyed by tag name.

    This is only a shallow conversation - child nodes are not recursively processed.
    """
    if node is None:
        return {}
    result = {}
    try:
        children = list(node)
    except Exception:
        # If node is not an Element-like object, return empty dict
        return {}
    for child in children:
        tag = getattr(child, 'tag', None)
        if tag is None:
            continue
        if tag in result:
            existing = result[tag]
            if isinstance(existing, list):
                existing.append(child)
            else:
                result[tag] = [existing, child]
        else:
            result[tag] = child
    return result

def get_nodeinfo_well_known_document(url, document_path=None):
    """Generate a NodeInfo .well-known document.

    See spec: http://nodeinfo.diaspora.software

    :arg url: The full base url with protocol, ie https://example.com
    :arg document_path: Custom NodeInfo document path if supplied (optional)
    :returns: dict
    """
    # Basic validation of url
    if not isinstance(url, str) or not url.strip():
        raise ValueError("url must be a non-empty string")
    url = url.rstrip("/")
    # Determine the path to the NodeInfo document
    if document_path:
        # Ensure it starts with a slash
        path = document_path if document_path.startswith("/") else f"/{document_path}"
    else:
        path = "/nodeinfo"
    href = f"{url}{path}"
    # Construct the .well-known document
    return {
        "links": [
            {
                "rel": "http://nodeinfo.diaspora.software/ns/schema/1.0",
                "href": href
            }
        ]
    }

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    if not document:
        return None
    # Try parsing as JSON first
    import json
    try:
        return json.loads(document)
    except json.JSONDecodeError:
        pass
    # Fallback to XRD (XML)
    try:
        import xml.etree.ElementTree as ET
        ns = {"xrd": "http://docs.oasis-open.org/wsfed/xrd/1.0"}
        root = ET.fromstring(document)
        result = {}
        subject = root.find('xrd:Subject', ns)
        if subject is not None and subject.text:
            result["subject"] = subject.text
        for link in root.findall('xrd:Link', ns):
            rel = link.attrib.get("rel")
            href = link.attrib.get("href")
            if rel and href:
                # If multiple links have same rel, keep the first
                result.setdefault(rel, href)
        return result
    except Exception:
        return None

def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
    """
    Try to retrieve an RFC7033 webfinger document. Does not raise if it fails.
    """
    try:
        host = handle.split('@')[1]
    except (IndexError, AttributeError):
        return None
    try:
        resource = quote(handle)
        url = f"https://{host}/.well-known/webfinger?resource={resource}"
        with closing(urlopen(url)) as page:
            content = page.read()
            if isinstance(content, bytes):
                return content.decode('utf-8', errors='replace')
            return content
    except Exception:
        return None

def retrieve_and_parse_diaspora_webfinger(handle):
    """
    Retrieve a and parse a remote Diaspora webfinger document.

    :arg handle: Remote handle to retrieve
    :returns: dict
    """
    # Validate handle format and extract host
    try:
        host = handle.split("@")[1]
    except (AttributeError, IndexError):
        logger.warning("retrieve_and_parse_diaspora_webfinger: invalid handle given: %s", handle)
        return None

    # Attempt to fetch webfinger via the standard path
    document, code, exception = fetch_document(
        host=host,
        path="/.well-known/webfinger?resource=acct:%s" % quote(handle),
    )
    if document and not exception and code == 200:
        return parse_diaspora_webfinger(document)

    # If direct webfinger lookup fails, fall back to host-meta
    hostmeta = retrieve_diaspora_host_meta(host)
    if not hostmeta:
        return None

    # Locate the LRDD link which contains the template for webfinger
    lrdd_link = hostmeta.find_link(rels="lrdd")
    if not lrdd_link:
        return None

    try:
        template = lrdd_link.template
        url = template.replace("{uri}", quote(handle))
    except Exception:
        return None

    # Fetch webfinger using the template URL
    document, code, exception = fetch_document(url)
    if exception or not document or code != 200:
        return None

    return parse_diaspora_webfinger(document)

def dict_insert(dic, val, key, *keys):
    """
    insert a value of a nested key into a dictionary

    to insert value for a nested key, all ancestor keys should be given as
    method's arguments

    example:
      dict_insert({}, 'val', 'key1.key2'.split('.'))

    :param dic: a dictionary object to insert the nested key value into
    :param val: a value to insert to the given dictionary
    :param key: first key in a chain of key that will store the value
    :param keys: sub keys in the keys chain
    """
    if not isinstance(dic, dict):
        raise TypeError("The first argument must be a dictionary")

    # Determine the full chain of keys.  If *keys is empty and ``key`` is an
    # iterable that is not a string, treat it as the key sequence.
    if not keys and isinstance(key, (list, tuple)) and not isinstance(key, str):
        key_chain = list(key)
    else:
        key_chain = [key] + list(keys)

    if not key_chain:
        raise ValueError("At least one key must be provided")

    current = dic
    for k in key_chain[:-1]:
        if not isinstance(current, dict):
            raise TypeError(f"Expected a dict at key '{k}', but got {type(current).__name__}")
        if k not in current:
            current[k] = {}
        elif not isinstance(current[k], dict):
            raise TypeError(f"Expected a dict at key '{k}', but got {type(current[k]).__name__}")
        current = current[k]

    # Set the final value
    if not isinstance(current, dict):
        raise TypeError(f"Expected a dict at final key, but got {type(current).__name__}")
    current[key_chain[-1]] = val
    return dic

def list_of_file_names(settings_dirs, spec_option=None):
    """Return a sorted list of fully-qualified file names from the given
    settings directory or directories, optionally filtering by a glob
    pattern or file extension.

    Parameters
    ----------
    settings_dirs : Union[str, Iterable[str]]
        One or more directories to search for files.
    spec_option : str, optional
        A glob pattern (e.g., ``*.ini``) or file extension (e.g., ``.ini``)
        to filter the returned file names.  If ``None``, all files are
        returned.

    Returns
    -------
    list[str]
        Sorted list of full file paths that match the ``spec_option``
        (if provided).  Returns an empty list if the directory cannot be
        accessed or if no matching files are found.
    """
    import os
    import fnmatch

    # Normalise ``settings_dirs`` to an iterable of paths
    if isinstance(settings_dirs, (str, bytes)):
        dirs = [settings_dirs]
    else:
        try:
            dirs = list(settings_dirs)
        except Exception:
            dirs = []

    matched_files = []
    for directory in dirs:
        if not isinstance(directory, (str, bytes)):
            continue  # skip invalid entries
        try:
            for name in os.listdir(directory):
                if spec_option is None:
                    matched = True
                else:
                    matched = fnmatch.fnmatch(name, spec_option)
                if matched:
                    full_path = os.path.join(directory, name)
                    if os.path.isfile(full_path):
                        matched_files.append(full_path)
        except OSError:
            # Skip directories that cannot be accessed
            continue

    return sorted(matched_files)

@classmethod
def ansible_config_manager(cls):
    """Gets the ansible config manager."""
    # Cache the manager in a class attribute to avoid recreating it.
    if not getattr(cls, "_ansible_config_manager", None):
        try:
            # Primary import path for recent Ansible versions
            from ansible.config.manager import AnsibleConfigManager
            manager = AnsibleConfigManager()
        except Exception:
            # Fallback import path for older Ansible releases
            try:
                from ansible import constants as ansible_constants
                manager = ansible_constants.AnsibleConfigManager()
            except Exception as e:
                raise RuntimeError(f"Failed to load Ansible config manager: {e}")
        cls._ansible_config_manager = manager
    return cls._ansible_config_manager

def plugins_manager(cls):
    """Gets the plugin manager. """
    try:
        return cls._plugin_manager
    except AttributeError:
        raise RuntimeError('Plugin manager not initialized.')

@classmethod
def validate_from_file(cls, yaml_file=None):
    """
    Loads & validates that a YAML file has all required fields

    :param yaml_file: Path to YAML file
    :raise IRValidatorException: when mandatory data is missing in file
    :return: Dictionary with data loaded from a YAML file
    """
    if yaml_file is None:
        raise ValueError("yaml_file argument must be supplied")
    try:
        with open(yaml_file, "r") as f:
            data = yaml.safe_load(f)
    except Exception as exc:
        raise IRValidatorException(
            f"Error loading YAML file '{yaml_file}': {exc}"
        ) from exc
    if not isinstance(data, dict):
        raise IRValidatorException(
            f"YAML content for '{yaml_file}' must be a mapping, got {type(data).__name__}"
        )
    required = getattr(cls, "required_fields", set())
    missing = [field for field in required if field not in data]
    if missing:
        raise IRValidatorException(
            f"Mandatory fields missing from '{yaml_file}': {', '.join(missing)}"
        )
    return data

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files.

    This helper expands nested ``include`` directives that specify other
    section definitions.  The ``include`` key may contain:

        * a single string – name of the section in ``parser_dict`` to merge
        * a list of strings – merge each section
        * a dict mapping names to file paths – load the JSON/YAML file and merge

    The function is safe against circular includes and missing sections.
    It returns a new dictionary with all includes resolved.

    Parameters
    ----------
    parser_dict : dict
        The original parser dictionary that may contain ``include`` directives.

    Returns
    -------
    dict
        A new dictionary with ``include`` directives expanded.
    """
    import json
    import yaml
    from collections import deque

    def _load_from_path(path):
        """Try to load a JSON or YAML file from *path*."""
        try:
            with open(path, "r", encoding="utf-8") as f:
                if path.lower().endswith(".json"):
                    return json.load(f)
                if path.lower().endswith((".yaml", ".yml")):
                    return yaml.safe_load(f)
        except Exception:
            pass
        return None

    # Deep copy is not strictly required as we avoid mutation of the input.
    result = {}
    seen = set()          # keep track of already expanded sections
    work = deque([(None, parser_dict)])  # (current key prefix, section dict)

    while work:
        prefix, section = work.popleft()
        for key, value in section.items():
            if key == "include":
                # Normalize to a list of things to include
                includes = value
                if isinstance(includes, (str, int, float)):
                    includes = [includes]
                elif isinstance(includes, dict):
                    includes = list(includes.values())
                elif not isinstance(includes, (list, tuple)):
                    continue

                for inc in includes:
                    # If inc is a string pointing to a file, load it
                    if isinstance(inc, str) and (inc.endswith(".json") or inc.endswith((".yml", ".yaml"))):
                        inc_dict = _load_from_path(inc)
                        if inc_dict is None:
                            continue
                    else:
                        inc_dict = parser_dict.get(inc)

                    if not isinstance(inc_dict, dict):
                        continue

                    inc_key = f"{prefix}.{inc}" if prefix else inc
                    if inc_key in seen:
                        # Skip circular references
                        continue
                    seen.add(inc_key)
                    work.append((inc_key, inc_dict))
                continue

            # For normal key-value pairs, merge directly
            if isinstance(value, dict) and isinstance(result.get(key), dict):
                # Merge sub-dicts
                merged = result[key].copy()
                merged.update(value)
                result[key] = merged
            else:
                result[key] = value

    return result

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources. """
    defaults = {}
    # pull defaults from the spec object, if present
    if hasattr(self, "spec"):
        spec_obj = getattr(self, "spec")
        try:
            # try to use the spec object's attributes as defaults
            defaults.update(vars(spec_obj))
        except Exception:
            # if vars() fails or spec_obj has no __dict__, ignore
            pass
    # update with defaults defined on individual arguments/options
    if hasattr(self, "args"):
        for arg in getattr(self, "args"):
            # Argument objects are expected to have a `name` and optional `default` attribute
            try:
                name = getattr(arg, "name", None)
                if not name:
                    continue
                if hasattr(arg, "default"):
                    defaults[name] = arg.default
            except Exception:
                # If any unexpected attribute errors occur, skip this argument
                continue
    return defaults

def get_deprecated_args(self):
    """Returning dict with options which deprecate others. """
    return {
        # 'old_option': 'new_option',
    }

def get_option_spec(self, command_name, argument_name):
    """Gets the specification for the specified option name. """
    if not isinstance(command_name, str) or not isinstance(argument_name, str):
        raise TypeError("command_name and argument_name must be strings")

    # Retrieve the command-specific options dictionary.
    try:
        command_opts = self._option_spec.get(command_name)
    except AttributeError:
        raise AttributeError("The object has no '_option_spec' attribute")
    if command_opts is None:
        raise KeyError(f"Command '{command_name}' not found in option specifications")

    # Retrieve the specific argument specification.
    spec = command_opts.get(argument_name)
    if spec is None:
        raise KeyError(
            f"Option '{argument_name}' not found for command '{command_name}'"
        )

    return spec

def get_silent_args(self, args):
    """list of silenced argument

    :param args: The received arguments.
    :return: list, slienced argument names
    """
    # Ensure args is a list-like structure
    if args is None:
        return []
    if isinstance(args, str):
        args = [args]
    # Use a predefined set of silent argument identifiers if available
    silent_set = getattr(self, "SILENT_ARGS", None)
    if silent_set is None:
        return []
    # Normalize potential sets/lists/tuples to a set for efficient lookup
    if not isinstance(silent_set, (set, list, tuple)):
        silent_set = {silent_set}
    else:
        silent_set = set(silent_set)
    return [arg for arg in args if arg in silent_set]

def validate_requires_args(self, args):
        """Check if all the required arguments have been provided."""
        # Determine the list of required argument names.
        try:
            required = self.required_args
        except AttributeError:
            raise AttributeError("Instance does not have a 'required_args' attribute.")
        if not isinstance(required, (list, tuple, set)):
            raise TypeError("'required_args' must be a sequence of argument names.")

        # The args argument should be a mapping of names to values.
        if not isinstance(args, dict):
            raise TypeError("'args' must be a dictionary mapping argument names to values.")

        # Identify any missing or unset required arguments.
        missing = [name for name in required if name not in args or args[name] is None]
        if missing:
            raise ValueError(f"Missing required argument(s): {', '.join(missing)}")
        return True

def _get_conditionally_required_args(self, command_name, options_spec, args):
        """List arguments with ``required_when`` condition matched.

        :param command_name: the command name.
        :param options_spec:  the list of command spec options.
        :param args: the received input arguments
        :return: list, list of argument names with matched ``required_when``
            condition
        """
        required_names = []

        # Helper to evaluate a single condition
        def _eval_condition(condition):
            try:
                # If condition is a mapping, look up by command_name
                if isinstance(condition, dict):
                    # Expect mapping: command_name -> bool or callable
                    val = condition.get(command_name, False)
                    if callable(val):
                        return bool(val(args))
                    return bool(val)

                # If condition is callable, call it with args
                if callable(condition):
                    return bool(condition(args))

                # If condition is a string, interpret as Python expression
                if isinstance(condition, str):
                    # Create environment with args and command_name
                    env = {'command_name': command_name}
                    if isinstance(args, dict):
                        env.update(args)
                    return bool(eval(condition, {}, env))

                # Fallback: interpret truthiness directly
                return bool(condition)
            except Exception:
                # On any error, treat condition as not met
                return False

        for opt in options_spec:
            # Extract the option name
            name = None
            if isinstance(opt, dict):
                name = opt.get('name')
                condition = opt.get('required_when')
            else:
                name = getattr(opt, 'name', None)
                condition = getattr(opt, 'required_when', None)

            if not name or condition is None:
                continue

            if _eval_condition(condition):
                required_names.append(name)

        return required_names

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    # No arguments to validate
    if not args:
        return

    # Acquire argument specifications from the parsed YAML if available
    arg_specs = {}
    try:
        arg_specs = self.parsed_yaml.get('args', {})
    except AttributeError:
        # Safe guard if parsed_yaml or args key not present
        pass

    # Normalize args into a list of (name, value) tuples
    items = []
    if isinstance(args, dict):
        items = list(args.items())
    elif isinstance(args, list):
        for element in args:
            if isinstance(element, dict):
                items.extend(element.items())
    else:
        # Unsupported type: ignore validation
        return

    for arg_name, value in items:
        # Skip arguments without a value
        if value is None:
            continue

        # Retrieve max_length constraint if defined
        spec = arg_specs.get(arg_name, {})
        maxlen = spec.get('max_length')
        if maxlen is None:
            continue

        # Ensure maxlen is a non-negative integer
        if not isinstance(maxlen, int) or maxlen < 0:
            raise ValueError(
                f"Invalid max_length for argument '{arg_name}': {maxlen}"
            )

        # Measure the length of the value as a string
        try:
            length = len(str(value))
        except Exception:
            # If conversion to string fails, skip the check
            continue

        if length > maxlen:
            raise ValueError(
                f"Argument '{arg_name}' exceeds maximum length of {maxlen} characters (got {length})."
            )

def validate_choices_args(self, args):
    """
    Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    if not isinstance(args, dict):
        raise TypeError("args must be a dict of argument name to value")

    # Try to retrieve the argument definitions that contain possible choices.
    # The concrete attribute name may vary; common patterns are 'arg_defs'
    # or 'choices'.
    arg_defs = getattr(self, 'arg_defs', {})
    choices_map = getattr(self, 'choices', {})

    # Merge definitions from both possible sources if they exist.
    if not arg_defs and choices_map:
        arg_defs = {name: {'choices': val} for name, val in choices_map.items()}

    for arg_name, arg_value in args.items():
        # Get the definition for this argument.
        definition = arg_defs.get(arg_name) if arg_defs else None

        # If the definition has a 'choices' entry, enforce it.
        if definition and 'choices' in definition:
            allowed = definition['choices']
            # Accept iterable values (for multi-valued options).
            if isinstance(arg_value, (list, tuple)):
                for val in arg_value:
                    if val not in allowed:
                        raise ValueError(
                            f"Invalid value for argument '{arg_name}': "
                            f"{val!r}. Must be one of {allowed!r}.")
            else:
                if arg_value not in allowed:
                    raise ValueError(
                        f"Invalid value for argument '{arg_name}': "
                        f"{arg_value!r}. Must be one of {allowed!r}.")

def validate_min_max_args(self, args):
    """
    Check if value of arguments is between minimum and maximum values.
    The *args* argument should be an iterable of tuples, each containing
    (value, minimum, maximum) in that order.  Alternatively it can be a
    mapping where each item maps a key to a tuple of the same
    structure.  The method validates that *minimum* is not greater than
    *maximum* and that *value* is within [minimum, maximum].
    Any invalid input raises an exception.  If all arguments are valid,
    the original *args* object is returned unchanged.
    """
    # Allow mapping or iterable of tuples
    if isinstance(args, dict):
        items = args.items()
    else:
        items = enumerate(args)

    for key, item in items:
        try:
            value, minimum, maximum = item
        except Exception:
            raise TypeError(
                f"Argument {key!r} must be a tuple of (value, min, max); got {item!r}"
            )

        # Ensure minimum <= maximum
        try:
            if minimum > maximum:
                raise ValueError
        except TypeError:
            raise TypeError(
                f"Minimum and maximum for argument {key!r} must be comparable "
                f"types; got {minimum!r} and {maximum!r}"
            )

        # Ensure value is within bounds
        try:
            if not (minimum <= value <= maximum):
                raise ValueError
        except TypeError:
            raise TypeError(
                f"Value for argument {key!r} must be comparable with "
                f"its bounds; got {value!r}"
            )

    return args

def get_nested_custom_and_control_args(self, args):
    """Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    # Default to empty dicts if no arguments provided
    if not args:
        return {}, {}

    if not isinstance(args, dict):
        raise TypeError("args must be a dictionary, got %r" % type(args).__name__)

    control_args = {}
    nested_args = {}

    for key, value in args.items():
        if not isinstance(key, str):
            raise TypeError("Argument keys must be strings, got %r" % type(key).__name__)

        # Detect control arguments by a 'control_' prefix.
        # Custom arguments are treated as nested arguments by default.
        if key.startswith('control_'):
            # Strip the prefix for the control arguments dictionary
            control_key = key[len('control_') :]
            control_args[control_key] = value
        else:
            nested_args[key] = value

    return control_args, nested_args

@staticmethod
def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``.

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of dictionaries containing extra variables
    :returns: the updated vars_dict
    """
    if not isinstance(vars_dict, dict):
        raise ValueError("vars_dict must be a dictionary")

    if not extra_vars:
        return vars_dict

    # Accept a single dictionary as extra_vars
    if isinstance(extra_vars, dict):
        extra_vars = [extra_vars]
    elif not isinstance(extra_vars, (list, tuple)):
        raise ValueError("extra_vars must be a dict, list, or tuple")

    for item in extra_vars:
        if not isinstance(item, dict):
            raise ValueError("Each item in extra_vars must be a dictionary")
        vars_dict.update(item)

    return vars_dict

def get_plugin_spec_flatten_dict(plugin_dir):
    """
    Creates a flat dict from the plugin spec.

    :param plugin_dir: A path to the plugin's dir or the plugin.json file itself.
    :return: A flatten dictionary contains the plugin's properties.
    """
    import json
    import os

    # Resolve the path: if a directory is given, look for plugin.json inside it;
    # otherwise assume the passed path is the spec file itself.
    spec_path = plugin_dir
    if os.path.isdir(plugin_dir):
        spec_path = os.path.join(plugin_dir, "plugin.json")

    if not os.path.exists(spec_path):
        raise FileNotFoundError(f"Plugin spec not found: {spec_path}")

    try:
        with open(spec_path, "r", encoding="utf-8") as fp:
            spec = json.load(fp)
    except json.JSONDecodeError as exc:
        raise ValueError(f"Invalid JSON in {spec_path}: {exc}") from exc
    except OSError as exc:
        raise IOError(f"Could not read plugin spec {spec_path}: {exc}") from exc

    def _flatten(d, parent_key="", sep="."):
        items = {}
        for k, v in d.items():
            new_key = f"{parent_key}{sep}{k}" if parent_key else k
            if isinstance(v, dict):
                items.update(_flatten(v, new_key, sep=sep))
            else:
                items[new_key] = v
        return items

    return _flatten(spec)

def inject_config(self):
    """Set the environment variable for config path, if it is undefined."""
    env_var = 'CONFIG_PATH'
    # Retrieve current value; if none, set it from the instance
    try:
        current = os.environ.get(env_var)
    except Exception:
        # If environment variables cannot be accessed for some reason, skip injection
        return
    if current is None:
        # Only set if the instance has a valid config_path attribute
        if hasattr(self, 'config_path') and self.config_path:
            os.environ[env_var] = str(self.config_path)  # Convert to string in case of Path
        else:
            # If no config_path is available, do not set anything
            pass
    # No explicit return value needed; the method modifies os.environ in place.

def extend_cli(self, root_subparsers):
    """
    Adds the spec cli options to to the main entry point.

    :param subparser: the subparser object to extend.
    """
    # Ensure the input is iterable of parsers
    if not root_subparsers:
        raise ValueError("root_subparsers must be provided and not empty")
    try:
        # Support both dict of name->parser and iterable of parsers
        if isinstance(root_subparsers, dict):
            parser_iter = root_subparsers.values()
        else:
            parser_iter = root_subparsers
        for parser in parser_iter:
            parser.add_argument(
                '--spec',
                '-s',
                dest='spec',
                help='Target spec to operate on',
                required=False
            )
    except Exception as exc:
        raise RuntimeError(f"Failed to extend CLI parsers: {exc}") from exc
    return None

def strip_root(path, root):
    """Remove root from path, throw exception on failure."""
    import os
    if not isinstance(path, str) or not isinstance(root, str):
        raise TypeError("Both path and root must be strings")
    abspath = os.path.abspath(path)
    abroot = os.path.abspath(root)
    try:
        relative = os.path.relpath(abspath, abroot)
    except ValueError as exc:
        raise ValueError(f"Cannot strip root '{root}' from path '{path}': {exc}") from exc
    if relative == os.curdir:
        return ''
    if relative == os.pardir or relative.startswith(os.pardir + os.sep):
        raise ValueError(f"Root '{root}' is not a parent of path '{path}'")
    return relative
